    requests.map(async (request) => {
      const response = await request();
      const extractedItems = extractTransactionItems(response);
      if (extractedItems.length) {
        successful.push(...extractedItems);
        onPartial?.([...successful]);
      }
      return response;
    })
  );

  if (successful.length === 0) {
    throw firstRejectedReason(results);
  }

  return successful;
};

