+
+export const collectTokenRoles = (decoded) => {
+  if (!decoded || typeof decoded !== "object") {
+    return [];
+  }
+
+  const collectedRoles = [];
+
+  appendRoles(collectedRoles, decoded?.realm_access?.roles);
+  appendRoles(collectedRoles, decoded?.roles);
