                        "Restore STP check requires manual flow for requestId={} -> S7, failures={} durationMs={} totalDurationMs={}",
                        requestId,
                        stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                        stpDurationMs,
                        System.currentTimeMillis() - startedAt);
                return false;
            }

            LOG.info(
                    "Restore STP check passed for requestId={} -> S9, failures={} durationMs={}",
                    requestId,
                    stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                    stpDurationMs);
            return true;
        });
        return Boolean.TRUE.equals(autoReady);
    }

    public void continueFromStpAfterRestore(Long requestId) {
        if (requestId == null) {
            return;
        }
        long startedAt = System.currentTimeMillis();
        try {
            boolean autoReady = runStpAfterRestoreInTransaction(requestId, startedAt);
            if (!autoReady) {
                return;
            }
            long dispatchStartedAt = System.currentTimeMillis();
            prepareAndSendToDestinationAfterRestore(requestId);
            LOG.info(
                    "Restore STP-only outbound dispatch finished requestId={} durationMs={} totalDurationMs={}",
                    requestId,
                    System.currentTimeMillis() - dispatchStartedAt,
                    System.currentTimeMillis() - startedAt);
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId,
                    "Greska u restore STP nastavku",
                    ex.getMessage());
            throw ex;
        }
    }

    private boolean runStpAfterRestoreInTransaction(Long requestId, long startedAt) {
        TransactionTemplate transactionTemplate = new TransactionTemplate(transactionManager);
        Boolean autoReady = transactionTemplate.execute(status -> {
            LOG.info("Restore STP-only flow start requestId={}", requestId);
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new IllegalStateException("Transaction not found for requestId=" + requestId));
            String currentStage = normalize(txn.getStatus());
            LOG.info("Restore STP-only current stage requestId={} currentStage={}", requestId, currentStage);

            long stpStartedAt = System.currentTimeMillis();
            Optional<StpManualCheckResponse> stpResult =
                    validationEvaluationService.isManualProcessingRequiredByRequestIdAfterRestore(requestId);
            if (stpResult.isEmpty()) {
                throw new IllegalStateException("STP validation flow failed: transaction not found for requestId=" + requestId);
            }
            long stpDurationMs = System.currentTimeMillis() - stpStartedAt;
            if (stpResult.get().isManualRequired()) {
                LOG.info(
                        "Restore STP-only check requires manual flow for requestId={} -> S7, failures={} durationMs={} totalDurationMs={}",
                        requestId,
                        stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                        stpDurationMs,
                        System.currentTimeMillis() - startedAt);
                return false;
            }

            LOG.info(
                    "Restore STP-only check passed for requestId={} -> S9, failures={} durationMs={}",
                    requestId,
                    stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                    stpDurationMs);
            return true;
        });
        return Boolean.TRUE.equals(autoReady);
    }

    public void prepareAndSendToDestinationAfterRestore(Long requestId) {
        if (requestId == null) {
            return;
        }
        LOG.info("Restore response orchestration start requestId={}", requestId);
        CbrTransactionResponse response = responseService.prepareResponseAfterRestore(requestId);
        String destination = normalize(response != null ? response.getDestinationSystem() : null);
        LOG.info(
                "Restore response prepared requestId={} responseId={} destination={} communicationCode={}",
                requestId,
                response != null ? response.getId() : null,
                destination,
                response != null ? response.getCommunicationCode() : null);
        MqMessageService mqMessageService = mqMessageServiceProvider.getIfAvailable();
        if (mqMessageService == null) {
            throw new IllegalStateException("MQ message service is not available for OM/GSE dispatch.");
        }
        if ("OM".equalsIgnoreCase(destination)) {
            LOG.info("Restore dispatching prepared response for requestId={} to OM", requestId);
            mqMessageService.sendCbrRequestToOm(requestId);
            LOG.info("Restore finished dispatch for requestId={} to OM", requestId);
            return;
        }
        if ("GSE".equalsIgnoreCase(destination)) {
            LOG.info("Restore dispatching prepared response for requestId={} to GSE", requestId);
            mqMessageService.sendCbrRequestToGse(requestId);
            LOG.info("Restore finished dispatch for requestId={} to GSE", requestId);
            return;
        }
        throw new IllegalStateException("Unsupported destination system for requestId=" + requestId + ": " + destination);
    }

    private String normalize(String value) {
        return value == null ? null : value.trim();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}

