import { notification } from "antd";
import { jwtDecode } from "jwt-decode";
import KeycloakService, { isKeycloakInUsage } from "./KeycloakService";
import { collectTokenRoles, hasAnyRequiredRole, parseStoredRoles } from "./roleUtils";
import { JWT_ROLES, JWT_TOKEN } from "./storageKeys";

const TOKEN_PREFIX = "Bearer ";
const EXP_SKEW_SECONDS = 30;
let didWarnMissingContainerAuth = false;

const normalizeToken = (token) => {
  if (!token || typeof token !== "string") return null;
  return token.startsWith(TOKEN_PREFIX) ? token.slice(TOKEN_PREFIX.length) : token;
};

const getTokenFromKeycloak = () => {
  if (!isKeycloakInUsage()) return null;
  return KeycloakService.getToken();
};

const normalizeText = (value) => {
  if (value === null || value === undefined) return null;
  const normalized = String(value).trim().replace(/\s+/g, " ");
  return normalized || null;
};

const normalizeComparableText = (value) =>
  normalizeText(value)?.toLocaleLowerCase() || null;

const pickFirstText = (...values) => {
  for (const value of values) {
    const normalized = normalizeText(value);
    if (normalized) {
      return normalized;
    }
  }
  return null;
};

const hasRepeatedIdenticalWords = (value) => {
  const normalized = normalizeText(value);
  if (!normalized) return false;

  const parts = normalized
    .split(" ")
    .map((part) => normalizeComparableText(part))
    .filter(Boolean);

  if (parts.length < 2) {
    return false;
  }

  return parts.every((part) => part === parts[0]);
};

const extractGivenNameFromName = (nameValue, familyName) => {
  const normalizedName = normalizeText(nameValue);
  if (!normalizedName) return null;
  if (!familyName) return normalizedName;

  const comparableFamilyName = normalizeComparableText(familyName);
  const filteredParts = normalizedName
    .split(" ")
    .map((part) => normalizeText(part))
    .filter(Boolean)
    .filter((part) => normalizeComparableText(part) !== comparableFamilyName);

  return pickFirstText(filteredParts.join(" "), normalizedName);
};

export const getToken = () =>
  normalizeToken(localStorage.getItem(JWT_TOKEN)) ||
  normalizeToken(getTokenFromKeycloak());

const isInContainer = () =>
  process.env.ENV_START_TYPE !== "isolation" &&
  process.env.ENV_AUTH_TYPE !== "local";

const notifyMissingContainerAuth = () => {
  if (!isInContainer() || didWarnMissingContainerAuth) return;
  didWarnMissingContainerAuth = true;
  notification.error({
    message: "Autentikacija nije dostupna",
    description:
      "Container nije upisao JWT podatke u storage. Proveri container login/session.",
  });
};

export const getBearerToken = () => {
  const token = getToken();
  return token ? `${TOKEN_PREFIX}${token}` : null;
};

// App no longer manages auth persistence; storage is controlled by the container.
export const currentUser = () => {
  const decoded = getDecodedToken();
  return (
    decoded?.preferred_username ||
    decoded?.username ||
    decoded?.email ||
    decoded?.sub ||
    null
  );
};

export const getDisplayName = () => {
  const decoded = getDecodedToken();
  if (!decoded) {
    return currentUser();
  }

  const explicitGivenName = pickFirstText(
    decoded?.given_name,
    decoded?.givenName,
    decoded?.first_name,
    decoded?.firstName
  );
  const familyName = pickFirstText(
    decoded?.family_name,
    decoded?.familyName,
    decoded?.last_name,
    decoded?.lastName
  );
  const tokenName = pickFirstText(decoded?.name);
  const fullName = pickFirstText(
    decoded?.display_name,
    decoded?.displayName,
    decoded?.full_name,
    decoded?.fullName
  );
  const givenNameFromToken = extractGivenNameFromName(tokenName, familyName);
  const explicitGivenNameMatchesFamilyName =
    explicitGivenName &&
    familyName &&
    normalizeComparableText(explicitGivenName) ===
      normalizeComparableText(familyName);
  const givenName = explicitGivenNameMatchesFamilyName
    ? givenNameFromToken
    : explicitGivenName || givenNameFromToken;
  const resolvedFullName =
    fullName ||
    (tokenName?.includes(" ") && !hasRepeatedIdenticalWords(tokenName)
      ? tokenName
      : null);

  if (givenName && familyName) {
    if (normalizeComparableText(givenName) !== normalizeComparableText(familyName)) {
      return `${familyName} ${givenName}`;
    }

    if (resolvedFullName && !hasRepeatedIdenticalWords(resolvedFullName)) {
      return resolvedFullName;
    }

    return familyName;
  }

  if (resolvedFullName && !hasRepeatedIdenticalWords(resolvedFullName)) {
    return resolvedFullName;
  }

  return (
    givenName ||
    familyName ||
    tokenName ||
    currentUser()
  );
};

export const getUserRoles = () => {
  const decoded = getDecodedToken();
  const tokenRoles = collectTokenRoles(decoded);
  if (tokenRoles.length > 0) {
    return tokenRoles;
  }

  const roles = localStorage.getItem(JWT_ROLES);
  return parseStoredRoles(roles);
};

export const getDecodedToken = () => {
  const token = getToken();
  if (!token) return null;
  try {
    return jwtDecode(token);
  } catch (error) {
    return null;
  }
};

export const isTokenExpired = (decoded, skewSeconds = EXP_SKEW_SECONDS) => {
  if (!decoded || !decoded.exp) return true;
  const nowSeconds = Math.floor(Date.now() / 1000);
  return nowSeconds >= decoded.exp - skewSeconds;
};

export const isAuthenticated = () => {
  const token = getToken();
  if (!token) {
    notifyMissingContainerAuth();
    return false;
  }
  const decoded = getDecodedToken();
  if (isTokenExpired(decoded)) return false;
  return Boolean(currentUser());
};

export const isAuthorized = (requiredRoles = []) => {
  return hasAnyRequiredRole(getUserRoles(), requiredRoles);
};

