package rs.unicredit.cbr.service;

import java.time.LocalDateTime;
import java.util.Optional;
import java.util.UUID;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.dto.TransactionLockResponse;
import rs.unicredit.cbr.model.CbrTransactionLock;
import rs.unicredit.cbr.repository.CbrTransactionLockRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;

@Service
@RequiredArgsConstructor
public class TransactionLockService {

    private static final String TX_LOCKED_PREFIX = "TX_LOCKED::";

    private final CbrTransactionLockRepository transactionLockRepository;
    private final CbrTransactionRepository transactionRepository;
    private final CurrentUserService currentUserService;

    @Value("${customs.tx-lock.ttl-seconds:60}")
    private long lockTtlSeconds;

    @Transactional
    public TransactionLockResponse acquire(Long transactionId, String sessionId) {
        requireTransactionId(transactionId);
        ensureTransactionExists(transactionId);

        String currentUsername = resolveCurrentUsername();
        String resolvedSessionId = resolveSessionId(sessionId);
        LocalDateTime now = LocalDateTime.now();

        CbrTransactionLock existingLock = findActiveLock(transactionId, now).orElse(null);
        if (existingLock == null) {
            CbrTransactionLock lock = CbrTransactionLock.builder()
                    .transactionId(transactionId)
                    .lockedBy(currentUsername)
                    .sessionId(resolvedSessionId)
                    .lockedAt(now)
                    .expiresAt(now.plusSeconds(lockTtlSeconds))
                    .build();
            return toResponse(transactionLockRepository.save(lock), currentUsername);
        }

        if (equalsIgnoreCase(existingLock.getLockedBy(), currentUsername)) {
            existingLock.setSessionId(resolvedSessionId);
            existingLock.setLockedAt(now);
            existingLock.setExpiresAt(now.plusSeconds(lockTtlSeconds));
            return toResponse(transactionLockRepository.save(existingLock), currentUsername);
        }

        throw lockedByAnotherUser(existingLock.getLockedBy());
    }

    @Transactional
    public TransactionLockResponse refresh(Long transactionId, String sessionId) {
        requireTransactionId(transactionId);
        String currentUsername = resolveCurrentUsername();
        String resolvedSessionId = resolveSessionId(sessionId);
        LocalDateTime now = LocalDateTime.now();

        CbrTransactionLock existingLock = findActiveLock(transactionId, now)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "TX_LOCK_MISSING"));

        if (!equalsIgnoreCase(existingLock.getLockedBy(), currentUsername)) {
            throw lockedByAnotherUser(existingLock.getLockedBy());
        }
        if (!equals(existingLock.getSessionId(), resolvedSessionId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "TX_LOCK_SESSION_MISMATCH");
        }

        existingLock.setLockedAt(now);
        existingLock.setExpiresAt(now.plusSeconds(lockTtlSeconds));
        return toResponse(transactionLockRepository.save(existingLock), currentUsername);
    }

    @Transactional
    public TransactionLockResponse release(Long transactionId, String sessionId) {
        requireTransactionId(transactionId);
        String currentUsername = resolveCurrentUsername();
        String resolvedSessionId = resolveSessionId(sessionId);
        LocalDateTime now = LocalDateTime.now();

        CbrTransactionLock existingLock = findActiveLock(transactionId, now).orElse(null);
        if (existingLock == null) {
            return TransactionLockResponse.builder()
                    .transactionId(transactionId)
                    .locked(false)
                    .ownedByCurrentUser(false)
                    .build();
        }

        if (!equalsIgnoreCase(existingLock.getLockedBy(), currentUsername)) {
            throw lockedByAnotherUser(existingLock.getLockedBy());
        }
        if (!equals(existingLock.getSessionId(), resolvedSessionId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "TX_LOCK_SESSION_MISMATCH");
        }

        transactionLockRepository.delete(existingLock);
        return TransactionLockResponse.builder()
                .transactionId(transactionId)
                .locked(false)
                .ownedByCurrentUser(false)
                .build();
    }

    @Transactional
    public TransactionLockResponse getStatus(Long transactionId) {
        requireTransactionId(transactionId);
        String currentUsername = resolveCurrentUsername();
        LocalDateTime now = LocalDateTime.now();

        return findActiveLock(transactionId, now)
                .map(lock -> toResponse(lock, currentUsername))
                .orElse(TransactionLockResponse.builder()
                        .transactionId(transactionId)
                        .locked(false)
                        .ownedByCurrentUser(false)
                        .build());
    }

    @Transactional
    public void assertCanMutate(Long transactionId) {
        requireTransactionId(transactionId);
        String currentUsername = resolveCurrentUsername();
        LocalDateTime now = LocalDateTime.now();

        Optional<CbrTransactionLock> maybeLock = findActiveLock(transactionId, now);
        if (maybeLock.isEmpty()) {
            return;
        }

        CbrTransactionLock existingLock = maybeLock.get();
        if (!equalsIgnoreCase(existingLock.getLockedBy(), currentUsername)) {
            throw lockedByAnotherUser(existingLock.getLockedBy());
        }
    }

    private Optional<CbrTransactionLock> findActiveLock(Long transactionId, LocalDateTime now) {
        Optional<CbrTransactionLock> maybeLock = transactionLockRepository.findById(transactionId);
        if (maybeLock.isEmpty()) {
            return Optional.empty();
        }

        CbrTransactionLock lock = maybeLock.get();
        if (lock.getExpiresAt() != null && lock.getExpiresAt().isAfter(now)) {
            return Optional.of(lock);
        }

        transactionLockRepository.delete(lock);
        return Optional.empty();
    }

    private TransactionLockResponse toResponse(CbrTransactionLock lock, String currentUsername) {
        return TransactionLockResponse.builder()
                .transactionId(lock.getTransactionId())
                .locked(true)
                .ownedByCurrentUser(equalsIgnoreCase(lock.getLockedBy(), currentUsername))
                .lockedBy(lock.getLockedBy())
                .sessionId(lock.getSessionId())
                .lockedAt(lock.getLockedAt())
                .expiresAt(lock.getExpiresAt())
                .build();
    }

    private void ensureTransactionExists(Long transactionId) {
        if (!transactionRepository.existsById(transactionId)) {
            throw new ResponseStatusException(
                    HttpStatus.NOT_FOUND,
                    "Transaction not found for id=" + transactionId);
        }
    }

    private void requireTransactionId(Long transactionId) {
        if (transactionId == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "transactionId is required");
        }
    }

    private String resolveCurrentUsername() {
        String username = currentUserService.getUsername();
        if (username == null || username.isBlank()) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Current user is not authenticated.");
        }
        return username.trim();
    }

    private String resolveSessionId(String sessionId) {
        if (sessionId != null && !sessionId.isBlank()) {
            return sessionId.trim();
        }
        return UUID.randomUUID().toString();
    }

    private boolean equalsIgnoreCase(String left, String right) {
        if (left == null || right == null) {
            return false;
        }
        return left.equalsIgnoreCase(right);
    }

    private boolean equals(String left, String right) {
        if (left == null || right == null) {
            return false;
        }
        return left.equals(right);
    }

    private ResponseStatusException lockedByAnotherUser(String lockedBy) {
        String lockOwner = lockedBy == null || lockedBy.isBlank() ? "UNKNOWN" : lockedBy.trim();
        return new ResponseStatusException(HttpStatus.CONFLICT, TX_LOCKED_PREFIX + lockOwner);
    }
}

