            LOG.info(
                    "Restore-from-error resolved requestId={} currentStage={} targetStage={} executePostActions={} postActions={}",
                    requestId,
                    currentStage,
                    targetStageCode,
                    executePostActions,
                    postActions);
            LOG.info(
                    "Restore-from-error starting requestId={} transactionId={} callReplyRef={} currentStage={} targetStage={}",
                    requestId,
                    managedTxn.getId(),
                    managedTxn.getCallReplyRef(),
                    currentStage,
                    targetStageCode);
            String resolvedNote = isBlank(note)
                    ? "Auto-restore from S11 to " + targetStageCode + " (Last Non-S11)"
                    : note;

            StageRestoreRequest restoreRequest = StageRestoreRequest.builder()
                    .requestId(requestId)
                    .transactionId(managedTxn.getId())
                    .snapshotId(snapshot.getId())
                    .stageCode(targetStageCode)
                    .executePostActions(false)
                    .postActions(List.of())
                    .note(resolvedNote)
                    .build();

            // The request is leaving the technical error state, so stale error text must not survive restore.
            managedRequest.setErrorMessage(null);
            StageRestoreResponse restoreResponse = restoreFromSnapshot(restoreRequest);
            return new RestoreFromErrorContext(
                    restoreResponse,
                    targetStageCode,
                    postActions,
                    managedTxn.getId(),
                    managedTxn.getCallReplyRef());
        });

        if (restoreContext == null) {
            throw new IllegalStateException("Restore transaction finished without response for requestId=" + requestId);
        }

        StageRestoreResponse restoreResponse = restoreContext.restoreResponse();
        String targetStageCode = restoreContext.targetStageCode();
        assertCommittedRestoreState(requestId, targetStageCode);
        LOG.info(
                "Restore-from-error snapshot committed requestId={} transactionId={} restoredStage={} durationMs={}",
                requestId,
                restoreContext.transactionId(),
                restoreResponse.getRestoredStageCode(),
                System.currentTimeMillis() - startedAt);

        List<String> executedActions = new ArrayList<>();
        List<String> failedActions = new ArrayList<>();
        if (executePostActions) {
            for (String action : restoreContext.postActions()) {
                if (isBlank(action)) {
                    continue;
                }
                try {
                    executePostAction(requestId, action);
                    executedActions.add(normalize(action));
                } catch (Exception ex) {
                    String actionCode = normalize(action);
                    LOG.warn("Post action {} failed for requestId={}: {}", actionCode, requestId, ex.getMessage());
                    failedActions.add(actionCode + ": " + ex.getMessage());
                }
            }
        }

        String message = failedActions.isEmpty()
                ? "Snapshot restored to " + targetStageCode
                : "Snapshot restored to " + targetStageCode + ", but some post actions failed: "
                        + String.join(" | ", failedActions);
        StageRestoreResponse response = StageRestoreResponse.builder()
                .requestId(restoreResponse.getRequestId())
                .fromStageCode(restoreResponse.getFromStageCode())
                .restoredStageCode(restoreResponse.getRestoredStageCode())
                .snapshotId(restoreResponse.getSnapshotId())
                .postActionsExecuted(!executedActions.isEmpty())
                .executedActions(executedActions)
                .message(message)
                .build();
        long elapsedMs = System.currentTimeMillis() - startedAt;
        LOG.info(
                "Restore-from-error finished requestId={} transactionId={} restoredStage={} postActionsExecuted={} executedActions={} durationMs={}",
                requestId,
                restoreContext.transactionId(),
                response.getRestoredStageCode(),
                response.isPostActionsExecuted(),
                response.getExecutedActions(),
                elapsedMs);
        logRestoreFromErrorAction(requestId, restoreContext, response, executePostActions, note, failedActions);
        return response;
    }

    public StageRestoreResponse restoreFromLastNonErrorStageByTransactionId(
            Long transactionId,
            Long fallbackRequestId,
            String note,
            boolean executePostActions) {
        if (transactionId == null && fallbackRequestId == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "id is required");
        }

        if (transactionId != null) {
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsById(transactionId)
                    .orElseThrow(() -> new ResponseStatusException(
                            HttpStatus.UNPROCESSABLE_ENTITY,
                            "No transaction found for id=" + transactionId + ". Replay/re-ingest is required."));

            Long requestId = txn.getRequest() != null ? txn.getRequest().getId() : null;
            if (requestId == null) {
                throw new ResponseStatusException(
                        HttpStatus.UNPROCESSABLE_ENTITY,
                        "No requestId linked to transaction id=" + transactionId + ". Replay/re-ingest is required.");
            }

            return restoreFromLastNonErrorStage(requestId, note, executePostActions);
        }

        return restoreFromLastNonErrorStage(fallbackRequestId, note, executePostActions);
    }

    private SnapshotPayload parseSnapshot(String snapshotJson) {
        if (isBlank(snapshotJson)) {
            throw new IllegalStateException("Snapshot JSON is empty");
        }
        try {
            JsonNode root = objectMapper.readTree(snapshotJson);
            JsonNode txnNode = root.get("transaction");
            if (txnNode == null || txnNode.isNull()) {
                throw new IllegalStateException("Snapshot JSON does not contain transaction");
            }
            CbrTransaction snapshotTransaction = objectMapper.treeToValue(txnNode, CbrTransaction.class);
            List<CbrTransactionStat> snapshotStats = new ArrayList<>();
            JsonNode statsNode = root.get("regulatoryDetails");
            if (statsNode != null && statsNode.isArray()) {
                for (JsonNode node : statsNode) {
                    snapshotStats.add(objectMapper.treeToValue(node, CbrTransactionStat.class));
                }
            }
            return new SnapshotPayload(snapshotTransaction, snapshotStats);
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("Failed to parse snapshot JSON", ex);
        }
    }

    private void applyTransactionRestore(CbrTransaction target, SnapshotPayload payload) {
        CbrTransaction source = payload.transaction();
        BeanUtils.copyProperties(
                source,
                target,
                "id",
                "request",
                "regulatoryDetails",
                "status",
                "createdAt",
                "updatedAt");

        target.getRegulatoryDetails().clear();
        for (CbrTransactionStat snapshotStat : payload.regulatoryDetails()) {
            CbrTransactionStat stat = CbrTransactionStat.builder()
                    .transaction(target)
                    .splitStatCode(snapshotStat.getSplitStatCode())
                    .splitAmount(snapshotStat.getSplitAmount())
                    .splitAmountCurrency(snapshotStat.getSplitAmountCurrency())
                    .invoiceNumber(snapshotStat.getInvoiceNumber())
                    .invoiceYear(snapshotStat.getInvoiceYear())
                    .build();
            target.getRegulatoryDetails().add(stat);
        }
    }

    private void executePostAction(Long requestId, String action) {
        String code = normalize(action).toUpperCase(Locale.ROOT);
        long startedAt = System.currentTimeMillis();
        LOG.info("Executing restore post action requestId={} action={}", requestId, code);
        switch (code) {
            case "ORCHESTRATE_AFTER_INGESTION" ->
                messageOrchestrationService.orchestrateAfterIngestion(requestId);
            case "START_VALIDATION_FLOW" ->
                messageOrchestrationService.startValidationFlow(requestId, "Manual restore post action");
            case "START_VALIDATION_FLOW_AFTER_RESTORE" ->
                restoreMessageOrchestrationService.startValidationFlowAfterRestore(requestId, "Manual restore post action");
            case "RUN_STP_AFTER_RESTORE" ->
                restoreMessageOrchestrationService.continueFromStpAfterRestore(requestId);
            case "PREPARE_RESPONSE" -> responseService.prepareResponse(requestId);
            case "PREPARE_RESPONSE_AFTER_RESTORE" -> responseService.prepareResponseAfterRestore(requestId);
            case "SEND_TO_DESTINATION" -> sendToDestination(requestId);
            case "SEND_TO_DESTINATION_AFTER_RESTORE" -> restoreMessageOrchestrationService.prepareAndSendToDestinationAfterRestore(requestId);
            case "SEND_TO_OM" -> sendToOm(requestId);
            case "SEND_TO_GSE" -> sendToGse(requestId);
            default -> throw new IllegalArgumentException("Unsupported post action: " + action);
        }
        LOG.info(
                "Finished restore post action requestId={} action={} durationMs={}",
                requestId,
                code,
                System.currentTimeMillis() - startedAt);
    }

    private void logRestoreFromErrorAction(
            Long requestId,
            RestoreFromErrorContext restoreContext,
            StageRestoreResponse response,
            boolean executePostActions,
            String note,
            List<String> failedActions) {
        if (requestId == null || restoreContext == null || response == null) {
            return;
        }
        try {
            Map<String, Object> changes = new HashMap<>();
            changes.put("transactionId", restoreContext.transactionId());
            changes.put("callReplyRef", restoreContext.callReplyRef());
            changes.put("fromStage", response.getFromStageCode());
            changes.put("targetStage", response.getRestoredStageCode());
            changes.put("snapshotId", response.getSnapshotId());
            changes.put("note", note);
            changes.put("executePostActions", executePostActions);
            changes.put("executedActions", response.getExecutedActions());
            changes.put("postActionsExecuted", response.isPostActionsExecuted());
            changes.put("failedActions", failedActions == null ? List.of() : failedActions);
            actionLogService.logAction(requestId.toString(), ACTION_RESTORE_FROM_ERROR, changes);
        } catch (Exception ex) {
            LOG.warn(
                    "Failed to write action log for restore-from-error requestId={} transactionId={}: {}",
                    requestId,
                    restoreContext.transactionId(),
                    ex.getMessage());
        }
    }

    private List<String> resolvePostActions(String targetStageCode) {
        String normalizedStage = normalize(targetStageCode);
        if (isBlank(normalizedStage)) {
            return List.of();
        }

        if ("S2".equalsIgnoreCase(normalizedStage)) {
            return List.of("ORCHESTRATE_AFTER_INGESTION");
        }
        if ("S9".equalsIgnoreCase(normalizedStage)) {
            return List.of("SEND_TO_DESTINATION_AFTER_RESTORE");
        }
        if ("S10".equalsIgnoreCase(normalizedStage)) {
            return List.of();
        }
        if ("S8".equalsIgnoreCase(normalizedStage)) {
            return List.of("RUN_STP_AFTER_RESTORE");
        }
        if (VALIDATION_FLOW_STAGES.contains(normalizedStage.toUpperCase(Locale.ROOT))
                || EARLY_STAGES.contains(normalizedStage.toUpperCase(Locale.ROOT))) {
            return List.of("START_VALIDATION_FLOW_AFTER_RESTORE");
        }
        return List.of();
    }

    private void sendToDestination(Long requestId) {
        CbrTransactionResponse response = responseService.prepareResponse(requestId);
        String destination = normalize(response != null ? response.getDestinationSystem() : null);
        if ("OM".equalsIgnoreCase(destination)) {
            sendToOm(requestId);
            return;
        }
        if ("GSE".equalsIgnoreCase(destination)) {
            sendToGse(requestId);
            return;
        }
        throw new IllegalStateException("Unsupported destination system: " + destination);
    }

    private void sendToOm(Long requestId) {
        MqMessageService service = mqMessageServiceProvider.getIfAvailable();
        if (service == null) {
            throw new IllegalStateException("MQ message service is not available");
        }
        service.sendCbrRequestToOm(requestId);
    }

    private void sendToGse(Long requestId) {
        MqMessageService service = mqMessageServiceProvider.getIfAvailable();
        if (service == null) {
            throw new IllegalStateException("MQ message service is not available");
        }
        service.sendCbrRequestToGse(requestId);
    }

    private CbrTransactionRequest findRequestForUpdate(Long requestId) {
        try {
            Map<String, Object> properties = new HashMap<>();
            properties.put("jakarta.persistence.lock.timeout", 0);
            CbrTransactionRequest request = entityManager.find(
                    CbrTransactionRequest.class,
                    requestId,
                    LockModeType.PESSIMISTIC_WRITE,
                    properties);
            if (request == null) {
                throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Request not found: " + requestId);
            }
            return request;
        } catch (PessimisticLockException | LockTimeoutException ex) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Restore is already in progress for requestId=" + requestId,
                    ex);
        }
    }

    private CbrTransaction findTransactionForUpdate(Long requestId) {
        try {
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new ResponseStatusException(
                            HttpStatus.UNPROCESSABLE_ENTITY,
                            "No transaction found for requestId=" + requestId + ". Replay/re-ingest is required."));
            Map<String, Object> properties = new HashMap<>();
            properties.put("jakarta.persistence.lock.timeout", 0);
            entityManager.lock(txn, LockModeType.PESSIMISTIC_WRITE, properties);
            return txn;
        } catch (PessimisticLockException | LockTimeoutException ex) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Restore is already in progress for requestId=" + requestId,
                    ex);
        }
    }

    private void assertCommittedRestoreState(Long requestId, String expectedStageCode) {
        CbrTransactionRequest committedRequest = requestRepository.findById(requestId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Request not found after restore: " + requestId));
        CbrTransaction committedTxn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.UNPROCESSABLE_ENTITY,
                        "Transaction not found after restore for requestId=" + requestId));

        String requestStatus = normalize(committedRequest.getStatus());
        String transactionStatus = normalize(committedTxn.getStatus());
        String normalizedExpectedStage = normalize(expectedStageCode);
        LOG.info(
                "Restore-from-error committed state check requestId={} transactionId={} expectedStage={} requestStatus={} transactionStatus={}",
                requestId,
                committedTxn.getId(),
                normalizedExpectedStage,
                requestStatus,
                transactionStatus);

        boolean requestMatches = normalizedExpectedStage != null
                && normalizedExpectedStage.equalsIgnoreCase(requestStatus);
        boolean transactionMatches = normalizedExpectedStage != null
                && normalizedExpectedStage.equalsIgnoreCase(transactionStatus);
        if (!requestMatches || !transactionMatches) {
            LOG.error(
                    "Restore-from-error committed inconsistent state requestId={} transactionId={} expectedStage={} requestStatus={} transactionStatus={}",
                    requestId,
                    committedTxn.getId(),
                    normalizedExpectedStage,
                    requestStatus,
                    transactionStatus);
            throw new ResponseStatusException(
                    HttpStatus.INTERNAL_SERVER_ERROR,
                    "Restore committed inconsistent stage state for requestId=" + requestId
                            + " expected=" + normalizedExpectedStage
                            + " requestStatus=" + requestStatus
                            + " transactionStatus=" + transactionStatus);
        }
    }

    private String normalize(String value) {
        return value == null ? null : value.trim();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

