    @Transactional
    public TransactionLockResponse acquire(Long transactionId, String sessionId) {
        requireTransactionId(transactionId);
        ensureTransactionExists(transactionId);

        String currentUsername = resolveCurrentUsername();
        String resolvedSessionId = resolveSessionId(sessionId);
        LocalDateTime now = LocalDateTime.now();

        CbrTransactionLock existingLock = findActiveLock(transactionId, now).orElse(null);
        if (existingLock == null) {
