    }

    @PostMapping("/{transactionId}/lock/refresh")
    @PreAuthorize("@authz.hasAnyOf(authentication,'ADMIN','SENIOR','JUNIOR')")
    public ResponseEntity<TransactionLockResponse> refreshLock(
            @PathVariable Long transactionId,
            @RequestBody(required = false) TransactionLockRequest request) {
        return ResponseEntity.ok(
                transactionLockService.refresh(transactionId, request != null ? request.getSessionId() : null));
    }

    @DeleteMapping("/{transactionId}/lock")
    @PreAuthorize("@authz.hasAnyOf(authentication,'ADMIN','SENIOR','JUNIOR')")
    public ResponseEntity<TransactionLockResponse> releaseLock(
            @PathVariable Long transactionId,
            @RequestBody(required = false) TransactionLockRequest request) {
        return ResponseEntity.ok(
                transactionLockService.release(transactionId, request != null ? request.getSessionId() : null));
    }

