    @PreAuthorize("@authz.hasAnyOf(authentication,'ADMIN','SENIOR','JUNIOR','VIEW')")
    public ResponseEntity<TransactionLockResponse> getLockStatus(@PathVariable Long transactionId) {
        return ResponseEntity.ok(transactionLockService.getStatus(transactionId));
    }
