    private String resolveActionToken(String token, CbrTransaction txn, String fieldKey) {
        if (isBlank(token)) {
            return null;
        }
        String normalized = token.trim().toUpperCase(java.util.Locale.ROOT);
        // INP8/OUTP8 znaci: uzmi vrednost iz iste kolone originalne P8 poruke (IN/OUT) ako postoji.
        if ("INP8".equals(normalized)) {
            return resolveRelatedFieldValue(txn, TransferDirection.IN, fieldKey);
        }
        if ("OUTP8".equals(normalized)) {
            return resolveRelatedFieldValue(txn, TransferDirection.OUT, fieldKey);
        }
        if (normalized.startsWith("GETCLIENTFORSEPASERVICE_")) {
            return resolveGetClientForSepaValue(token, txn);
        }
        return resolveFieldValue(token, txn);
    }

