    private boolean applySplitActions(CbrTransaction entity, CbrValidationMatrix rule) {
        if (entity == null || rule == null) {
            return false;
        }

        String actionSplitStatCode = rule.getActionSplitStatCode();
        String actionSplitAmount = rule.getActionSplitAmount();
        String actionInvoiceNumber = rule.getActionInvoiceNumber();
        String actionInvoiceYear = rule.getActionInvoiceYear();

        boolean hasAnySplitAction = !isBlank(actionSplitStatCode)
                || !isBlank(actionSplitAmount)
                || !isBlank(actionInvoiceNumber)
                || !isBlank(actionInvoiceYear);
        if (!hasAnySplitAction) {
            return false;
        }

        TransferDirection relatedDirection = resolveRelatedDirectionForFullStatCopy(
                actionSplitStatCode,
                actionSplitAmount,
                actionInvoiceNumber,
                actionInvoiceYear);
        if (relatedDirection != null) {
            return replaceRegulatoryDetailsFromRelatedTransaction(entity, relatedDirection);
        }

        if (entity.getRegulatoryDetails() == null) {
            entity.setRegulatoryDetails(new ArrayList<>());
        }

        if (entity.getRegulatoryDetails().isEmpty()) {
            if (isExplicitNull(actionSplitStatCode)
                    || isExplicitNull(actionSplitAmount)
                    || isExplicitNull(actionInvoiceNumber)
                    || isExplicitNull(actionInvoiceYear)) {
                return false;
            }
            CbrTransactionStat stat = new CbrTransactionStat();
            stat.setTransaction(entity);
            entity.getRegulatoryDetails().add(stat);
        }

        boolean changed = false;
        for (CbrTransactionStat stat : entity.getRegulatoryDetails()) {
            changed |= applyActionValue(
                    actionSplitStatCode, stat.getSplitStatCode(), stat::setSplitStatCode,
                    entity, "SPLIT_STAT_CODE", true).applied;
            changed |= applyActionBigDecimalValue(
                    actionSplitAmount, stat.getSplitAmount(), stat::setSplitAmount,
                    entity, "SPLIT_AMOUNT", true).applied;
            changed |= applyActionValue(
                    actionInvoiceNumber, stat.getInvoiceNumber(), stat::setInvoiceNumber,
                    entity, "INVOICE_NUMBER", true).applied;
            changed |= applyActionValue(
                    actionInvoiceYear, stat.getInvoiceYear(), stat::setInvoiceYear,
                    entity, "INVOICE_YEAR", true).applied;
        }
        return changed;
    }

    private TransferDirection resolveRelatedDirectionForFullStatCopy(String... actionValues) {
        String relatedToken = null;
        for (String actionValue : actionValues) {
            String normalized = normalizeRelatedStatCopyToken(actionValue);
            if (normalized == null) {
                return null;
            }
            if (relatedToken == null) {
                relatedToken = normalized;
            } else if (!relatedToken.equals(normalized)) {
                return null;
            }
        }
        if ("INP8".equals(relatedToken)) {
            return TransferDirection.IN;
        }
        if ("OUTP8".equals(relatedToken)) {
            return TransferDirection.OUT;
        }
        return null;
    }

