    public ValidationApplyResult applyActionsByValidationNo(Long requestId, BigDecimal validationNo) {
        return applyActionsByValidationNo(requestId, validationNo, true);
    }

    private ValidationApplyResult applyActionsByValidationNo(Long requestId, BigDecimal validationNo, boolean transitionOnError) {
        if (requestId == null) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("REQUEST_ID_MISSING"))
                    .build();
        }
        if (validationNo == null) {
            return ValidationApplyResult.builder()
                    .validationNo(null)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }
        try {
            Optional<CbrTransaction> txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId);
            if (txn.isEmpty()) {
                return ValidationApplyResult.builder()
                        .validationNo(validationNo)
                        .matched(false)
                        .applied(false)
                        .failedConditions(List.of("TRANSACTION_NOT_FOUND_FOR_REQUEST"))
                        .build();
            }
            Optional<CbrValidationMatrix> rule = validationMatrixRepository.findFirstByValidationNo(validationNo);
            if (rule.isEmpty()) {
                return ValidationApplyResult.builder()
                        .validationNo(validationNo)
                        .matched(false)
                        .applied(false)
                        .failedConditions(List.of("RULE_NOT_FOUND"))
                        .build();
            }

            if (!matchesMessageTypeAndDirection(txn.get(), rule.get())) {
                LOG.info("Validation {} skipped: COND_MESSAGE_TYPE/COND_DIRECTION not matched",
                        rule.get().getValidationNo());
                return ValidationApplyResult.builder()
                        .validationNo(rule.get().getValidationNo())
                        .matched(false)
                        .applied(false)
                        .failedConditions(List.of("COND_MESSAGE_TYPE", "COND_DIRECTION"))
                        .build();
            }

            ValidationEvaluationResult evaluation = evaluate(txn.get(), rule.get());
            if (!evaluation.isMatched()) {
                return ValidationApplyResult.builder()
                        .validationNo(evaluation.getValidationNo())
                        .matched(false)
                        .applied(false)
                        .failedConditions(evaluation.getFailedConditions())
                        .build();
            }
            String appliedReportType = null;
            boolean appliedReport = false;
            String appliedInstrumentValue = null;
            boolean appliedInstrument = false;
            String appliedSpecialMarkValue = null;
            boolean appliedSpecialMark = false;
            boolean appliedOther = false;

            CbrTransaction entity = txn.get();
            ActionApplyResult reportResult = applyActionValue(
                    rule.get().getActionReportType(), entity.getReportType(), entity::setReportType,
                    entity, "REPORT_TYPE", false);
            appliedReportType = reportResult.value;
            appliedReport = reportResult.applied;

            ActionApplyResult instrumentResult = applyActionValue(
                    rule.get().getActionInstrument(), entity.getPaymentInstrument(), entity::setPaymentInstrument,
                    entity, "PAYMENT_INSTRUMENT", true);
            appliedInstrumentValue = instrumentResult.value;
            appliedInstrument = instrumentResult.applied;

            ActionApplyResult specialMarkResult = applyActionValue(
                    rule.get().getActionSpecialMark(), entity.getSpecialMark(), entity::setSpecialMark,
                    entity, "SPECIAL_MARK", true);
            appliedSpecialMarkValue = specialMarkResult.value;
            appliedSpecialMark = specialMarkResult.applied;
            String actionCustomerId = rule.get().getActionCustomerId();
            String customerIdOverride = resolveCustomerIdOverride(rule.get(), entity);
            boolean enforceCustomerOverride = customerIdOverride != null;
            if (isValidationNo(rule.get(), "66.4") && !enforceCustomerOverride) {
                actionCustomerId = "GETCLIENTFORSEPASERVICE_MATICNI(CREDITOR_ACCOUNT_NO)";
            }
            if (isValidationNo(rule.get(), "66.8")) {
                actionCustomerId = "GETCLIENTFORSEPASERVICE_BANKAMATICNI(CREDITOR_ACCOUNT_NO,CREDITOR_AGENT)";
            }
            String customerIdBefore = entity.getCustomerId();
            ActionApplyResult customerIdActionResult = applyActionValueWithOverride(
                    actionCustomerId, customerIdOverride, entity.getCustomerId(), entity::setCustomerId,
                    entity, "CUSTOMER_ID", !enforceCustomerOverride);
            appliedOther |= customerIdActionResult.applied;
            LOG.info(
                    "Validation {} CUSTOMER_ID action='{}' override='{}' before='{}' resolved='{}' after='{}' applied={}",
                    rule.get().getValidationNo(),
                    actionCustomerId,
                    customerIdOverride,
                    customerIdBefore,
                    customerIdActionResult.value,
                    entity.getCustomerId(),
                    customerIdActionResult.applied);
            String actionCountryCode1 = rule.get().getActionCountryCode1();
            appliedOther |= applyActionValue(
                    actionCountryCode1, entity.getCountryCode1(), entity::setCountryCode1,
                    entity, "COUNTRY_CODE1", true).applied;
            String actionCountryCode2 = rule.get().getActionCountryCode2();
            appliedOther |= applyActionValue(
                    actionCountryCode2, entity.getCountryCode2(), entity::setCountryCode2,
                    entity, "COUNTRY_CODE2", true).applied;
            String actionLoanNumber = rule.get().getActionLoanNumber();
            appliedOther |= applyActionValue(
                    actionLoanNumber, entity.getLoanNumber(), entity::setLoanNumber,
                    entity, "LOAN_NUMBER", true).applied;
            String actionLoanYear = rule.get().getActionLoanYear();
            appliedOther |= applyActionValue(
                    actionLoanYear, entity.getLoanYear(), entity::setLoanYear,
                    entity, "LOAN_YEAR", true).applied;
            String actionDrStatCode = rule.get().getActionDrStatCode();
            appliedOther |= applyActionValue(
                    actionDrStatCode, entity.getDrStatisticalCode(), entity::setDrStatisticalCode,
                    entity, "DR_STATISTICAL_CODE", true).applied;
            String actionCrStatCode = rule.get().getActionCrStatCode();
            appliedOther |= applyActionValue(
                    actionCrStatCode, entity.getCrStatisticalCode(), entity::setCrStatisticalCode,
                    entity, "CR_STATISTICAL_CODE", true).applied;
            appliedOther |= applySplitActions(entity, rule.get());
            if (isValidationNo(rule.get(), "77.3")) {
                appliedOther |= applyDrStatCodeFor77_3(entity);
                appliedOther |= applyCrStatCodeFor77_3(entity);
            }
            if (isValidationNo(rule.get(), "66.6")) {
                appliedOther |= applyDrStatCodeFor66_6(entity);
            }
            if (isValidationNo(rule.get(), "77.5")) {
                appliedOther |= applyDrStatCodeFor77_5(entity);
            }
            if (isValidationNo(rule.get(), "66.7")) {
                appliedOther |= applyDrStatCodeFor66_7(entity);
            }
            if (isValidationNo(rule.get(), "60.4")) {
                appliedOther |= applySplitDifferenceFor60_4(entity);
            }
            if (isValidationNo(rule.get(), "70.1")
                    || isValidationNo(rule.get(), "70.3")
