                appliedOther |= applySplitAmountDefault(entity);
            }

            if (appliedReport || appliedInstrument || appliedSpecialMark || appliedOther) {
                transactionRepository.save(entity);
            }

            return ValidationApplyResult.builder()
                    .validationNo(evaluation.getValidationNo())
                    .matched(true)
                    .applied(appliedReport || appliedInstrument || appliedSpecialMark || appliedOther)
                    .appliedReportType(appliedReportType)
                    .appliedInstrument(appliedInstrument)
                    .appliedPaymentInstrument(appliedInstrumentValue)
                    .appliedSpecialMark(appliedSpecialMark)
                    .appliedSpecialMarkValue(appliedSpecialMarkValue)
                    .failedConditions(List.of())
                    .build();
        } catch (Exception ex) {
            if (transitionOnError) {
                stageTransitionService.transitionErrorByRequestId(
                        requestId, "Greska pri primeni validation matrix akcija", ex.getMessage());
            }
            throw ex;
        }
    }

