    private boolean isPostMatrixValidationFailure(ValidationApplyResult result) {
        if (result == null || result.getValidationNo() == null) {
            return false;
        }
        if (result.getFailedConditions() == null || result.getFailedConditions().isEmpty()) {
            return false;
        }
        java.math.BigDecimal no = result.getValidationNo().stripTrailingZeros();
        if (no.scale() > 0) {
            return false;
        }
        return no.compareTo(java.math.BigDecimal.ONE) >= 0
                && no.compareTo(java.math.BigDecimal.valueOf(15L)) <= 0;
    }

