        boolean hasCreditorIban = false;
        for (String part : parts) {
            String normalized = part.trim().toUpperCase(java.util.Locale.ROOT);
            if ("DEBTOR_COUNTRY".equals(normalized)) {
                hasDebtorCountry = true;
            } else if ("CREDITOR_IBAN".equals(normalized)) {
                hasCreditorIban = true;
            }
        }
        return hasDebtorCountry && hasCreditorIban;
    }

    private boolean usesDebtorIbanCountry(String[] parts) {
        boolean hasCreditorCountry = false;
        boolean hasDebtorIban = false;
        for (String part : parts) {
            String normalized = part.trim().toUpperCase(java.util.Locale.ROOT);
            if ("CREDITOR_COUNTRY".equals(normalized)) {
                hasCreditorCountry = true;
            } else if ("DEBTOR_IBAN".equals(normalized)) {
                hasDebtorIban = true;
            }
        }
        return hasCreditorCountry && hasDebtorIban;
    }

    private String extractIbanCountry(String iban) {
        if (isBlank(iban)) {
            return null;
        }
        String trimmed = iban.trim();
        if (trimmed.length() < 2) {
            return null;
        }
        return trimmed.substring(0, 2);
    }

    private String resolveActionToken(String token, CbrTransaction txn, String fieldKey) {
        if (isBlank(token)) {
            return null;
        }
        String normalized = token.trim().toUpperCase(java.util.Locale.ROOT);
        // INP8/OUTP8 znaci: uzmi vrednost iz iste kolone originalne P8 poruke (IN/OUT) ako postoji.
        if ("INP8".equals(normalized)) {
            return resolveRelatedFieldValue(txn, TransferDirection.IN, fieldKey);
        }
        if ("OUTP8".equals(normalized)) {
            return resolveRelatedFieldValue(txn, TransferDirection.OUT, fieldKey);
        }
        if (normalized.startsWith("GETCLIENTFORSEPASERVICE_")) {
            return resolveGetClientForSepaValue(token, txn);
        }
        return resolveFieldValue(token, txn);
    }

