+    private boolean applyP8ReferenceForMatrixLink(CbrTransaction entity, CbrValidationMatrix rule) {
+        if (entity == null || rule == null || entity.getMessageType() != MessageType.P4) {
+            return false;
+        }
+        TransferDirection relatedDirection = resolveRelatedP8Direction(rule);
+        if (relatedDirection == null) {
+            return false;
+        }
+        Optional<CbrTransaction> related = findRelatedP8Transaction(entity, relatedDirection);
+        if (related.isEmpty()) {
+            return false;
+        }
