+    private TransferDirection resolveRelatedP8Direction(CbrValidationMatrix rule) {
+        if (rule == null) {
+            return null;
+        }
+        if (requiresOriginalP8ReportType70(rule)) {
+            return TransferDirection.OUT;
+        }
+        if (requiresOriginalP8ReportType60(rule)) {
+            return TransferDirection.IN;
+        }
+
+        TransferDirection resolvedDirection = null;
+        for (String actionValue : new String[] {
+                rule.getActionReportType(),
+                rule.getActionInstrument(),
+                rule.getActionSpecialMark(),
