+                rule.getActionLoanNumber(),
+                rule.getActionLoanYear(),
+                rule.getActionDrStatCode(),
+                rule.getActionCrStatCode(),
+                rule.getActionSplitStatCode(),
+                rule.getActionSplitAmount(),
+                rule.getActionInvoiceNumber(),
+                rule.getActionInvoiceYear() }) {
+            TransferDirection candidateDirection = resolveRelatedP8DirectionFromActionValue(actionValue);
+            if (candidateDirection == null) {
+                continue;
+            }
+            if (resolvedDirection == null) {
+                resolvedDirection = candidateDirection;
+                continue;
+            }
+            if (resolvedDirection != candidateDirection) {
+                return null;
+            }
+        }
+        return resolvedDirection;
+    }
