+    private TransferDirection resolveRelatedP8DirectionFromActionValue(String actionValue) {
+        if (isBlank(actionValue)) {
+            return null;
+        }
+        String trimmed = stripNullDirective(actionValue);
+        if (isBlank(trimmed)) {
+            return null;
+        }
+        String normalized = trimmed.trim().toUpperCase(java.util.Locale.ROOT);
+        if (normalized.startsWith("COALESCE(") && normalized.endsWith(")")) {
+            String inner = normalized.substring("COALESCE(".length(), normalized.length() - 1);
+            TransferDirection resolvedDirection = null;
+            for (String part : inner.split(",")) {
+                TransferDirection candidateDirection = resolveRelatedP8DirectionFromActionValue(part);
+                if (candidateDirection == null) {
+                    continue;
+                }
+                if (resolvedDirection == null) {
+                    resolvedDirection = candidateDirection;
+                    continue;
+                }
+                if (resolvedDirection != candidateDirection) {
+                    return null;
+                }
+            }
+            return resolvedDirection;
+        }
+        if ("INP8".equals(normalized)) {
+            return TransferDirection.IN;
+        }
+        if ("OUTP8".equals(normalized)) {
+            return TransferDirection.OUT;
+        }
+        return null;
+    }
