const EMPTY_VALUE = "-";

const firstDefined = (...values) =>
  values.find((value) => value !== null && value !== undefined && value !== "");

const parseDateSortValue = (value) => {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (value instanceof Date) {
    const timestamp = value.getTime();
    return Number.isNaN(timestamp) ? null : timestamp;
  }

  const asText = String(value).trim();
  if (!asText || asText === "-") {
    return null;
  }

  const localDateMatch = asText.match(
    /^(\d{2})[\/.](\d{2})[\/.](\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?$/
  );
  if (localDateMatch) {
    const [, day, month, year, hours = "00", minutes = "00", seconds = "00"] =
      localDateMatch;
    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const isoLikeDateMatch = asText.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2})(?::(\d{2}))?)?/
  );
  if (isoLikeDateMatch) {
    const [, year, month, day, hours = "00", minutes = "00", seconds = "00"] =
      isoLikeDateMatch;
    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const parsed = Date.parse(asText);
  return Number.isNaN(parsed) ? null : parsed;
};

const resolveReceivedDateSource = (item = {}) =>
  firstDefined(
    item?.createdAt,
    item?.created_at,
    item?.sourceReceivedAt,
    item?.receivedAt,
    item?.receivedDate,
    item?.dateReceived,
    item?.processingDate,
    item?.createdOn,
    item?.createdDate
  );

const toComparableId = (value) => {
  if (value === null || value === undefined) return "";
  return String(value);
};

const formatDate = (value) => {
  if (!value) return EMPTY_VALUE;

  const parsedDate = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsedDate.getTime())) return String(value);

  const day = String(parsedDate.getDate()).padStart(2, "0");
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const year = parsedDate.getFullYear();
  return `${day}/${month}/${year}`;
};

const formatDateTime = (value) => {
  if (!value) return EMPTY_VALUE;

  const parsedDate = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsedDate.getTime())) return String(value);

  const day = String(parsedDate.getDate()).padStart(2, "0");
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const year = parsedDate.getFullYear();
  const hours = String(parsedDate.getHours()).padStart(2, "0");
  const minutes = String(parsedDate.getMinutes()).padStart(2, "0");

  return `${day}/${month}/${year} ${hours}:${minutes}`;
};

const formatBoolean = (value) => {
  if (value === null || value === undefined || value === "") return EMPTY_VALUE;

  if (typeof value === "boolean") return value ? "Da" : "Ne";
  if (typeof value === "number") {
    if (value === 1) return "Da";
    if (value === 0) return "Ne";
    return String(value);
  }

  const normalized = String(value).trim().toLowerCase();
  if (["true", "da", "yes", "y", "d", "1"].includes(normalized)) return "Da";
  if (["false", "ne", "no", "n", "0"].includes(normalized)) return "Ne";
  return String(value);
};

const shortenName = (value) => {
  if (!value) return EMPTY_VALUE;
  const normalized = String(value).trim();
  if (!normalized) return EMPTY_VALUE;

  const parts = normalized.split(/\s+/);
  if (parts.length < 2) return normalized;
  return `${parts[0][0]}. ${parts[parts.length - 1]}`;
};

