import React from "react";
import { Button, Tag, Tooltip, Typography } from "antd";
import {
  CloseOutlined,
  CopyOutlined,
  InfoCircleOutlined,
  LockOutlined,
} from "@ant-design/icons";
import styles from "./Drawer.module.css";

const normalizeStpValue = (value) => {
  if (value === null || value === undefined || value === "") {
    return "-";
  }

  const normalized = String(value).trim().toLowerCase();
  if (["true", "da", "yes", "y", "d", "1"].includes(normalized)) {
    return "DA";
  }
  if (["false", "ne", "no", "n", "0"].includes(normalized)) {
    return "NE";
  }
  return String(value).trim();
};

const Header = ({
  title = "Pregled poruke",
  reference,
  status,
  customerStp,
  lockBadge,
  onClose,
}) => {
  const copyReference = async () => {
    if (!reference || !navigator?.clipboard?.writeText) {
      return;
    }
    try {
      await navigator.clipboard.writeText(String(reference));
    } catch {
      // no-op
    }
  };

  return (
    <div className={styles.drawerHeader}>
      <div className={styles.drawerHeaderLeft}>
        <Typography.Text className={styles.drawerHeaderTitle}>{title}</Typography.Text>
        {reference ? (
          <div className={styles.drawerHeaderReferenceWrap}>
            <Typography.Text className={styles.drawerHeaderReference}>{reference}</Typography.Text>
            <Tooltip title="Copy">
              <Button
                type="text"
                icon={<CopyOutlined />}
                onClick={copyReference}
                className={styles.drawerHeaderCopyButton}
                aria-label="Copy reference"
              />
            </Tooltip>
          </div>
        ) : null}
        {status ? (
          <Tag icon={<InfoCircleOutlined />} className={styles.drawerHeaderStatusTag}>
            {status}
          </Tag>
        ) : null}
        <Tag className={styles.drawerHeaderStpTag}>
          {`STP: ${normalizeStpValue(customerStp)}`}
        </Tag>
        {lockBadge ? (
          <Tag icon={<LockOutlined />} className={styles.drawerHeaderLockTag}>
            {lockBadge}
          </Tag>
        ) : null}
      </div>
      <Button
        type="text"
        icon={<CloseOutlined />}
        onClick={onClose}
        className={styles.drawerHeaderCloseButton}
        aria-label="Close drawer"
      />
    </div>
  );
};

export default Header;

