package rs.unicredit.cbr.service;

import java.util.List;

import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.dto.GlFeeListItemDto;
import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
public class GlFeeQueryService {

    private final GlFeeDataRepository glFeeDataRepository;

    @Transactional(readOnly = true)
    public List<GlFeeListItemDto> getAll() {
        return glFeeDataRepository.findAll(Sort.by(Sort.Direction.DESC, "id"))
                .stream()
                .map(this::toDto)
                .toList();
    }

    private GlFeeListItemDto toDto(GlFeeData entity) {
        return GlFeeListItemDto.builder()
                .id(entity.getId())
                .requestId(entity.getRequestId())
                .callReplyRef(entity.getCallReplyRef())
                .messageType(entity.getMessageType())
                .direction(entity.getDirection())
                .segment(entity.getSegment())
                .creditorAgent(entity.getCreditorAgent())
                .creditorLrc(entity.getCreditorLrc())
                .debtorLrc(entity.getDebtorLrc())
                .crStatisticalCode(entity.getCrStatisticalCode())
                .amount(entity.getAmount())
                .amountRsd(entity.getAmountRsd())
                .middrate(entity.getMiddrate())
                .sdc(entity.getSdc())
                .creditAccount(entity.getCreditAccount())
                .debitAccount(entity.getDebitAccount())
                .fee(entity.getFee())
                .appliedFeeRuleNo(entity.getAppliedFeeRuleNo())
                .budgetCode(entity.getBudgetCode())
                .transactionCode(entity.getTransactionCode())
                .currency(entity.getCurrency())
                .narrative1(entity.getNarrative1())
                .narrative2(entity.getNarrative2())
                .opu(entity.getOpu())
                .reportingDate(entity.getReportingDate())
                .valueDate(entity.getValueDate())
                .bookingStatus(entity.getBookingStatus())
                .build();
    }
}

