package rs.unicredit.cbr.mq;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jms.annotation.JmsListener;
import org.springframework.jms.support.JmsHeaders;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.stereotype.Component;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;

import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.SkipperTransactionRequest;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;
import rs.unicredit.cbr.repository.SkipperTransactionRequestRepository;
import rs.unicredit.cbr.service.Pacs002SkipperParserService;

@Component
@ConditionalOnProperty(prefix = "customs.mq", name = "enabled", havingValue = "true")
public class SkipperMqListener {

    private static final Logger LOG = LoggerFactory.getLogger(SkipperMqListener.class);

    private final SkipperTransactionRequestRepository skipperRepository;
    private final CbrTransactionRequestRepository cbrRequestRepository;
    private final Pacs002SkipperParserService skipperParserService;

    public SkipperMqListener(
            SkipperTransactionRequestRepository skipperRepository,
            CbrTransactionRequestRepository cbrRequestRepository,
            Pacs002SkipperParserService skipperParserService) {
        this.skipperRepository = skipperRepository;
        this.cbrRequestRepository = cbrRequestRepository;
        this.skipperParserService = skipperParserService;
    }

    @JmsListener(destination = "${customs.mq.inbound-queue}", containerFactory = "mqListenerContainerFactory")
    public void onMessage(
            String payload,
            @Header(name = JmsHeaders.CORRELATION_ID, required = false) String correlationId,
            @Header(name = "request_id", required = false) String requestIdHeader) {
        int payloadSize = payload != null ? payload.length() : 0;
        LOG.info("Received Skipper MQ message (size={} chars, correlationId={}, request_id={})",
                payloadSize, correlationId, requestIdHeader);

        SkipperTransactionRequest skipperRequest = new SkipperTransactionRequest();
        skipperRequest.setSourceSystem("SKIPPER_MQ");
        String requestIdValue = firstNonBlank(requestIdHeader, correlationId);
        skipperRequest.setCorrelationId(requestIdValue);
        skipperRequest.setRawXml(payload);
        skipperRequest.setStatus("S1");
        skipperRepository.save(skipperRequest);

        if (requestIdValue == null) {
            LOG.info("Received Skipper message without request_id/correlationId; stored as skipperRequestId={}",
                    skipperRequest.getId());
            return;
        }
        try {
            Long requestId = Long.valueOf(requestIdValue);
            cbrRequestRepository.findById(requestId).ifPresentOrElse(request -> {
                LOG.info("Found CBR request for incoming Skipper message requestId={} (request_id={}, correlationId={})",
                        requestId, requestIdHeader, correlationId);
                try {
                    skipperParserService.parseAndApply(skipperRequest, request);
                } catch (Exception e) {
                    LOG.error("Failed to parse Skipper pacs.002 for requestId={} (request_id={}, correlationId={})",
                            requestId, requestIdHeader, correlationId, e);
                }
            }, () -> LOG.warn("No CBR request found for requestId={} (request_id={}, correlationId={})",
                    requestId, requestIdHeader, correlationId));
        } catch (NumberFormatException e) {
            LOG.warn("Received Skipper message with non-numeric request id value={} (request_id={}, correlationId={})",
                    requestIdValue, requestIdHeader, correlationId);
        }
    }

    private String firstNonBlank(String primary, String fallback) {
        if (primary != null && !primary.isBlank()) {
            return primary.trim();
        }
        if (fallback != null && !fallback.isBlank()) {
            return fallback.trim();
        }
        return null;
    }
}

