    @Bean("omMqCachingConnectionFactory")
    @ConditionalOnProperty(prefix = "customs.mq-om", name = "enabled", havingValue = "true")
    public ConnectionFactory omMqCachingConnectionFactory(
            @Qualifier("omMqConnectionFactory") MQConnectionFactory baseFactory) {
        CachingConnectionFactory cachingConnectionFactory = new CachingConnectionFactory(baseFactory);
        cachingConnectionFactory.setReconnectOnException(true);
        cachingConnectionFactory.setSessionCacheSize(3);
        return cachingConnectionFactory;
    }

    @Bean("gseMqListenerContainerFactory")
    @ConditionalOnProperty(prefix = "customs.mq-gse", name = "enabled", havingValue = "true")
    public DefaultJmsListenerContainerFactory gseMqListenerContainerFactory(
            @Qualifier("gseMqCachingConnectionFactory") ConnectionFactory connectionFactory) {
