import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.service.GetClientForSepaService.AccountRole;

@Service
@RequiredArgsConstructor
public class MessageOrchestrationService {

    private static final Logger LOG = LoggerFactory.getLogger(MessageOrchestrationService.class);

    private final CbrTransactionRepository transactionRepository;
    private final ValidationEvaluationService validationEvaluationService;
    private final StageTransitionService stageTransitionService;
    private final CbrTransactionResponseService responseService;
    private final ObjectProvider<MqMessageService> mqMessageServiceProvider;
    private final GetClientForSepaService getClientForSepaService;

    public void orchestrateAfterIngestion(Long requestId) {
        if (requestId == null) {
            return;
        }
        try {
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new IllegalStateException("Transaction not found for requestId=" + requestId));
            LOG.info(
                    "Starting post-ingestion orchestration requestId={} stage={} messageType={} direction={}",
                    requestId,
                    txn.getStatus(),
                    txn.getMessageType(),
                    txn.getDirection());

            triggerClientEnrichment(txn, requestId);
            LOG.info(
                    "Completed enrichment requestId={} customerId={} creditorName={} debtorName={} creditorRezident={}",
                    requestId,
                    txn.getCustomerId(),
                    txn.getCreditorName(),
                    txn.getDebtorName(),
                    txn.getCreditorRezident());

            boolean inPacs008 = MessageType.P8.equals(txn.getMessageType())
                    && TransferDirection.IN.equals(txn.getDirection());
            String creditorRezidentValue = normalize(txn.getCreditorRezident());
            boolean creditorRezident = "Y".equalsIgnoreCase(creditorRezidentValue)
                    || "R".equalsIgnoreCase(creditorRezidentValue);

            if (inPacs008 && creditorRezident) {
                MqMessageService mqMessageService = mqMessageServiceProvider.getIfAvailable();
                if (mqMessageService == null) {
                    throw new IllegalStateException("MQ message service is not available for Skipper routing.");
                }
                LOG.info("Routing requestId={} to Skipper (P8 IN + CREDITOR_REZIDENT in [Y,R])", requestId);
                mqMessageService.sendCbrRequestToSkipper(requestId);
                return;
            }

            LOG.info("Routing requestId={} to validation flow (not P8 IN resident branch)", requestId);
            startValidationFlow(requestId, "Poruka poslata na automatsku validaciju CBR");
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska u orkestraciji poruke", ex.getMessage());
            throw ex;
        }
    }

    public void startValidationFlow(Long requestId, String note) {
        runValidationFlow(requestId, note, false);
    }

    public void startValidationFlowAfterRestore(Long requestId, String note) {
        runValidationFlow(requestId, note, true);
    }

    private void runValidationFlow(Long requestId, String note, boolean afterRestore) {
        if (requestId == null) {
            return;
        }
        long startedAt = System.currentTimeMillis();
        try {
            LOG.info("Validation flow start requestId={} note={} afterRestore={}", requestId, note, afterRestore);
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new IllegalStateException("Transaction not found for requestId=" + requestId));
            String currentStage = normalize(txn.getStatus());
            if ("S6".equalsIgnoreCase(currentStage)) {
                LOG.info("Validation flow skipping duplicate S6 transition requestId={} currentStage={} afterRestore={}", requestId, currentStage, afterRestore);
            } else {
                long s6TransitionStartedAt = System.currentTimeMillis();
                stageTransitionService.transitionByRequestId(
                        requestId, "S6",
                        isBlank(note) ? "Poruka poslata na automatsku validaciju CBR" : note);
                LOG.info(
                        "Validation flow S6 transition finished requestId={} previousStage={} durationMs={}",
                        requestId,
                        currentStage,
                        System.currentTimeMillis() - s6TransitionStartedAt);
            }
            long validationStartedAt = System.currentTimeMillis();
            Optional<java.util.List<ValidationApplyResult>> results;
            if (afterRestore) {
                results = validationEvaluationService.evaluateAllByRequestIdAfterRestore(requestId);
            } else {
                results = validationEvaluationService.evaluateAllByRequestIdWithoutStageTransition(requestId);
            }
            if (results.isEmpty()) {
                throw new IllegalStateException("Validation flow failed: transaction not found for requestId=" + requestId);
            }
            long validationDurationMs = System.currentTimeMillis() - validationStartedAt;
            boolean anyApplied = results.get().stream().anyMatch(ValidationApplyResult::isApplied);
            boolean hasPostMatrixFailure =
                    validationEvaluationService.hasBlockingPostMatrixValidationFailure(results.get());
            boolean validationSchemaOk = anyApplied && !hasPostMatrixFailure;
            LOG.info(
                    "Validation flow matrix finished requestId={} resultsCount={} anyApplied={} hasPostMatrixFailure={} schemaOk={} durationMs={}",
                    requestId,
                    results.get().size(),
                    anyApplied,
                    hasPostMatrixFailure,
                    validationSchemaOk,
                    validationDurationMs);
            if (!afterRestore) {
                long validationStatusUpdateStartedAt = System.currentTimeMillis();
                validationEvaluationService.applyValidationStatuses(requestId, results.get());
                LOG.info(
                        "Validation flow status update finished requestId={} durationMs={} afterRestore={}",
                        requestId,
                        System.currentTimeMillis() - validationStatusUpdateStartedAt,
                        false);
            }
            if (!validationSchemaOk) {
                LOG.info(
                        "Validation schema NOT satisfied for requestId={} -> manual flow (S7), totalDurationMs={}",
                        requestId,
                        System.currentTimeMillis() - startedAt);
                return;
            }

            long stpStartedAt = System.currentTimeMillis();
            Optional<StpManualCheckResponse> stpResult;
            if (afterRestore) {
                stpResult = validationEvaluationService.isManualProcessingRequiredByRequestIdAfterRestore(requestId);
            } else {
                stpResult = validationEvaluationService.isManualProcessingRequiredByRequestIdWithoutStageTransition(requestId);
            }
            if (stpResult.isEmpty()) {
                throw new IllegalStateException("STP validation flow failed: transaction not found for requestId=" + requestId);
            }
            if (!afterRestore) {
                long stpStatusUpdateStartedAt = System.currentTimeMillis();
                validationEvaluationService.applyStpStatuses(requestId, stpResult.get());
                LOG.info(
                        "Validation flow STP status update finished requestId={} durationMs={} afterRestore={}",
                        requestId,
                        System.currentTimeMillis() - stpStatusUpdateStartedAt,
                        false);
            }
            long stpDurationMs = System.currentTimeMillis() - stpStartedAt;
            if (stpResult.get().isManualRequired()) {
                LOG.info(
                        "STP check requires manual flow for requestId={} -> S7, failures={} durationMs={} totalDurationMs={}",
                        requestId,
                        stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                        stpDurationMs,
                        System.currentTimeMillis() - startedAt);
            } else {
                LOG.info(
                        "STP check passed for requestId={} -> S9, failures={} durationMs={}",
                        requestId,
                        stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                        stpDurationMs);
                long dispatchStartedAt = System.currentTimeMillis();
                dispatchToExternalMq(requestId, afterRestore);
                LOG.info(
                        "Validation flow outbound dispatch finished requestId={} durationMs={} totalDurationMs={}",
                        requestId,
                        System.currentTimeMillis() - dispatchStartedAt,
                        System.currentTimeMillis() - startedAt);
            }
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska u automatskoj validaciji", ex.getMessage());
            throw ex;
        }
    }

    public void prepareAndSendToDestination(Long requestId) {
        if (requestId == null) {
            return;
        }
        dispatchToExternalMq(requestId, false);
    }

    public void prepareAndSendToDestinationAfterRestore(Long requestId) {
        if (requestId == null) {
            return;
        }
        dispatchToExternalMq(requestId, true);
    }

    private void triggerClientEnrichment(CbrTransaction txn, Long requestId) {
        if (txn == null || requestId == null) {
            return;
        }
        LOG.info("Starting client enrichment requestId={} direction={}", requestId, txn.getDirection());
        if (txn.getDirection() == TransferDirection.IN) {
            if (notBlank(txn.getCreditorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getCreditorAccountNo(), txn.getCreditorAgent(), requestId,
                        AccountRole.CREDITOR);
            } else {
                LOG.info("Skipping creditor enrichment requestId={} because creditorAccountNo is blank", requestId);
            }
            LOG.info("Finished client enrichment requestId={} direction=IN", requestId);
            return;
        }
        if (txn.getDirection() == TransferDirection.OUT) {
            if (notBlank(txn.getDebtorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getDebtorAccountNo(), txn.getDebtorAgent(), requestId,
                        AccountRole.DEBTOR);
            } else {
                LOG.info("Skipping debtor enrichment requestId={} because debtorAccountNo is blank", requestId);
            }
            LOG.info("Finished client enrichment requestId={} direction=OUT", requestId);
            return;
        }
        if (txn.getDirection() == TransferDirection.INT) {
            if (notBlank(txn.getCreditorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getCreditorAccountNo(), txn.getCreditorAgent(), requestId,
                        AccountRole.CREDITOR);
            } else {
                LOG.info("Skipping creditor enrichment requestId={} because creditorAccountNo is blank", requestId);
            }
            if (notBlank(txn.getDebtorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getDebtorAccountNo(), txn.getDebtorAgent(), requestId,
                        AccountRole.DEBTOR);
            } else {
                LOG.info("Skipping debtor enrichment requestId={} because debtorAccountNo is blank", requestId);
            }
            LOG.info("Finished client enrichment requestId={} direction=INT", requestId);
            return;
        }
        LOG.info(
                "Finished client enrichment requestId={} direction={} (no enrichment rule applied)",
                requestId,
                txn.getDirection());
    }

    private void dispatchToExternalMq(Long requestId, boolean afterRestore) {
        LOG.info("Starting response orchestration for requestId={} afterRestore={}", requestId, afterRestore);
        CbrTransactionResponse response = afterRestore
                ? responseService.prepareResponseAfterRestore(requestId)
                : responseService.prepareResponse(requestId);
        String destination = normalize(response != null ? response.getDestinationSystem() : null);
        LOG.info(
                "Prepared response for requestId={} responseId={} destination={} communicationCode={} afterRestore={}",
                requestId,
                response != null ? response.getId() : null,
                destination,
                response != null ? response.getCommunicationCode() : null,
                afterRestore);
        MqMessageService mqMessageService = mqMessageServiceProvider.getIfAvailable();
        if (mqMessageService == null) {
            throw new IllegalStateException("MQ message service is not available for OM/GSE dispatch.");
        }
        if ("OM".equalsIgnoreCase(destination)) {
            LOG.info("Dispatching prepared response for requestId={} to OM", requestId);
            mqMessageService.sendCbrRequestToOm(requestId);
            LOG.info("Finished dispatch for requestId={} to OM", requestId);
            return;
        }
        if ("GSE".equalsIgnoreCase(destination)) {
            LOG.info("Dispatching prepared response for requestId={} to GSE", requestId);
            mqMessageService.sendCbrRequestToGse(requestId);
            LOG.info("Finished dispatch for requestId={} to GSE", requestId);
            return;
        }
        throw new IllegalStateException("Unsupported destination system for requestId=" + requestId + ": " + destination);
    }

    private String normalize(String value) {
        return value == null ? null : value.trim();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private boolean notBlank(String value) {
        return !isBlank(value);
    }
}

