    private ClientData fetchAndUpdateByAccount(
            String account, String bic, Long requestId, AccountRole role, boolean transitionToS3) {
        ClientData clientData = fetchClientData(account, bic, requestId, role);
        if (clientData == null) {
            return null;
        }
        String cltId = clientData.cltId();
        boolean hasClientId = !isBlank(cltId);
        if (transitionToS3 && !hasClientId) {
            return null;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
        CbrTransaction txn = transactionRepository.findFirstByRequestId(requestId);
        if (txn == null) {
            throw new IllegalArgumentException("Transaction not found for request id: " + requestId);
        }
        if (role == AccountRole.DEBTOR) {
            if (hasClientId) {
                txn.setDebtorCoreId(cltId);
            }
            txn.setDebtorLrc(clientData.lrc());
            txn.setDebtorSegment(clientData.segment());
            txn.setDebtorCountryCode(clientData.countryCode());
            txn.setDebtorCustomerId(clientData.maticni());
            txn.setDebtorRezident(clientData.rezident());
            if (clientData.segment() != null && clientData.segment().length() > SEGMENT_MAX_LEN) {
                LOG.warn("Debtor segment too long for requestId={} account={} segment='{}' length={}",
                        requestId, account, clientData.segment(), clientData.segment().length());
            } else {
                LOG.info("Debtor segment mapping for requestId={} account={} segment='{}'",
                        requestId, account, clientData.segment());
            }
        } else if (role == AccountRole.CREDITOR) {
            if (hasClientId) {
                txn.setCreditorCoreId(cltId);
            }
            txn.setCreditorLrc(clientData.lrc());
            txn.setCreditorSegment(clientData.segment());
            txn.setCreditorCountryCode(clientData.countryCode());
            txn.setCreditorCustomerId(clientData.maticni());
            txn.setCreditorRezident(clientData.rezident());
            if (clientData.segment() != null && clientData.segment().length() > SEGMENT_MAX_LEN) {
                LOG.warn("Creditor segment too long for requestId={} account={} segment='{}' length={}",
                        requestId, account, clientData.segment(), clientData.segment().length());
            } else {
                LOG.info("Creditor segment mapping for requestId={} account={} segment='{}'",
                        requestId, account, clientData.segment());
            }
        }
        if (clientData.lei() != null) {
            if (txn.getMessageType() == rs.unicredit.cbr.model.MessageType.P8) {
                txn.setDebtorIdLei(clientData.lei());
            } else if (txn.getMessageType() == rs.unicredit.cbr.model.MessageType.P4) {
                txn.setCreditorIdLei(clientData.lei());
            }
        }
        if (!isBlank(account)) {
            String clientContract;
            try {
                clientContract = contractStatusService.fetchContractByAccount(account);
            } catch (Exception ex) {
                throw new IllegalStateException(String.format(
                        "Contract-status service call failed for requestId=%s account=%s role=%s: %s",
                        requestId, account, role, ex.getMessage()), ex);
            }
            if (clientContract != null && !clientContract.isBlank()) {
                txn.setClientContract(clientContract);
                LOG.info("Contract-status mapping for requestId={} account={} clientContract={}",
                        requestId, account, clientContract);
            }
        } else {
            LOG.info("Contract-status lookup skipped for requestId={} role={} because account is blank", requestId, role);
        }
        if (transitionToS3) {
            stageTransitionService.transition(request, txn, "S3", "Poruka obogacena sa core02 podacima");
        } else {
            transactionRepository.save(txn);
        }
        return clientData;
    }

    private ClientData fetchClientData(String account, String bic, Long requestId, AccountRole role) {
        try {
            URI uri = UriComponentsBuilder.fromHttpUrl(baseUrl)
                    .path("/clients")
                    .queryParamIfPresent("p_account", isBlank(account) ? java.util.Optional.empty() : java.util.Optional.of(account))
                    .queryParamIfPresent("p_bic", isBlank(bic) ? java.util.Optional.empty() : java.util.Optional.of(bic))
                    .build(true)
                    .toUri();
            ResponseEntity<com.fasterxml.jackson.databind.JsonNode> response =
                    restTemplate.getForEntity(uri, com.fasterxml.jackson.databind.JsonNode.class);
            if (!response.getStatusCode().is2xxSuccessful()) {
                return null;
            }
            com.fasterxml.jackson.databind.JsonNode root = response.getBody();
            if (root == null) {
                return null;
            }
            com.fasterxml.jackson.databind.JsonNode clientNode =
                    root.hasNonNull("client") ? root.get("client") : root;
            return objectMapper.treeToValue(clientNode, ClientData.class);
        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
            throw new IllegalStateException("Failed to parse GetClientForSepa response", ex);
        } catch (Exception ex) {
            throw new IllegalStateException(String.format(
                    "GetClientForSepa service call failed for requestId=%s account=%s role=%s: %s",
                    requestId, account, role, ex.getMessage()), ex);
        }
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
