import java.io.InputStream;
import java.net.http.HttpClient;
import java.time.Duration;
import java.security.KeyStore;

import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;

import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.core.io.ResourceLoader;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.web.client.RestTemplate;

import jakarta.annotation.PostConstruct;
import lombok.RequiredArgsConstructor;

@Configuration
@RequiredArgsConstructor
public class RestClientConfig {

    private final ResourceLoader resourceLoader;
    private SSLContext sslContext;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.get-client-for-sepa.ssl.trust-store:}")
    private String trustStore;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.get-client-for-sepa.ssl.trust-store-password:}")
    private String trustStorePassword;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.get-client-for-sepa.ssl.trust-store-type:JKS}")
    private String trustStoreType;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.contract-status.connect-timeout-ms:5000}")
    private long contractStatusConnectTimeoutMs;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.contract-status.read-timeout-ms:15000}")
    private long contractStatusReadTimeoutMs;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.wso2.x-api-key:}")
    private String wso2ApiKey;

    @PostConstruct
    public void configureSslContext() {
        if (trustStore == null || trustStore.isBlank()) {
            return;
        }
        try {
            Resource resource = resourceLoader.getResource(trustStore);
            if (!resource.exists()) {
                throw new IllegalStateException("Truststore not found: " + trustStore);
            }
            KeyStore keyStore = KeyStore.getInstance(trustStoreType);
            try (InputStream input = resource.getInputStream()) {
                keyStore.load(input, trustStorePassword != null ? trustStorePassword.toCharArray() : null);
            }
            TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            tmf.init(keyStore);
            sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, tmf.getTrustManagers(), null);
            SSLContext.setDefault(sslContext);
            javax.net.ssl.HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
        } catch (Exception e) {
            throw new IllegalStateException("Failed to initialize SSL truststore for GetClientForSepa", e);
        }
    }

    @Bean
    public RestTemplate restTemplate(RestTemplateBuilder builder) {
        ClientHttpRequestInterceptor apiKeyInterceptor = (request, body, execution) -> {
            if (wso2ApiKey != null && !wso2ApiKey.isBlank()) {
                request.getHeaders().set("x-api-key", wso2ApiKey.trim());
            }
            return execution.execute(request, body);
        };
        if (sslContext != null) {
            HttpClient httpClient = HttpClient.newBuilder()
                    .sslContext(sslContext)
                    .build();
            return builder
                    .requestFactory(() -> new JdkClientHttpRequestFactory(httpClient))
                    .additionalInterceptors(apiKeyInterceptor)
                    .build();
        }
        return builder.additionalInterceptors(apiKeyInterceptor).build();
    }

    @Bean("contractStatusRestTemplate")
    public RestTemplate contractStatusRestTemplate(RestTemplateBuilder builder) {
        ClientHttpRequestInterceptor apiKeyInterceptor = (request, body, execution) -> {
            if (wso2ApiKey != null && !wso2ApiKey.isBlank()) {
                request.getHeaders().set("x-api-key", wso2ApiKey.trim());
            }
            return execution.execute(request, body);
        };
        HttpClient.Builder httpClientBuilder = HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(Math.max(1000L, contractStatusConnectTimeoutMs)));
        if (sslContext != null) {
            httpClientBuilder.sslContext(sslContext);
        }
        JdkClientHttpRequestFactory requestFactory = new JdkClientHttpRequestFactory(httpClientBuilder.build());
        requestFactory.setReadTimeout(Duration.ofMillis(Math.max(1000L, contractStatusReadTimeoutMs)));
        return builder
                .requestFactory(() -> requestFactory)
                .additionalInterceptors(apiKeyInterceptor)
                .build();
    }
}

