package rs.unicredit.cbr.mq;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jms.annotation.JmsListener;
import org.springframework.jms.support.JmsHeaders;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.stereotype.Component;

import jakarta.jms.JMSException;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;
import rs.unicredit.cbr.service.Pacs004ParserService;
import rs.unicredit.cbr.service.Pacs008ParserService;
import rs.unicredit.cbr.service.StageTransitionService;

@Component
@ConditionalOnProperty(prefix = "customs.mq-gse", name = "enabled", havingValue = "true")
public class GseMqListener {

    private static final Logger LOG = LoggerFactory.getLogger(GseMqListener.class);

    private final CbrTransactionRequestRepository requestRepository;
    private final Pacs008ParserService pacs008ParserService;
    private final Pacs004ParserService pacs004ParserService;
    private final StageTransitionService stageTransitionService;

    public GseMqListener(
            CbrTransactionRequestRepository requestRepository,
            Pacs008ParserService pacs008ParserService,
            Pacs004ParserService pacs004ParserService,
            StageTransitionService stageTransitionService) {
        this.requestRepository = requestRepository;
        this.pacs008ParserService = pacs008ParserService;
        this.pacs004ParserService = pacs004ParserService;
        this.stageTransitionService = stageTransitionService;
    }

    @JmsListener(destination = "${customs.mq-gse.inbound-queue}", containerFactory = "gseMqListenerContainerFactory")
    public void onMessage(
            String payload,
            @Header(name = JmsHeaders.CORRELATION_ID, required = false) String correlationId)
            throws JMSException {
        int payloadSize = payload != null ? payload.length() : 0;
        LOG.info("Received GSE MQ message (size={} chars, correlationId={})", payloadSize, correlationId);

        CbrTransactionRequest request = new CbrTransactionRequest();
        request.setSourceSystem("GSE_MQ");
        request.setRawXml(payload);
        request.setStatus("S1");
        if (correlationId != null && !correlationId.isBlank()) {
            request.setCorrelationId(correlationId.trim());
            request.setCorrelationIdSource("INBOUND_HEADER");
        } else {
            request.setCorrelationId(java.util.UUID.randomUUID().toString());
            request.setCorrelationIdSource("GENERATED");
        }
        request = requestRepository.save(request);
        stageTransitionService.transition(request, null, "S1", "Poruka preuzeta sa GSE MQ");

        try {
            if (payload != null && payload.contains("pacs.004")) {
                pacs004ParserService.parseAndSave(request);
            } else {
                pacs008ParserService.parseAndSave(request);
            }
        } catch (Exception ex) {
            LOG.error("Failed to parse inbound GSE message requestId={}", request.getId(), ex);
        }
    }
}

