package rs.unicredit.cbr.service.impl;

import org.springframework.security.core.Authentication;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import org.springframework.stereotype.Component;
import rs.unicredit.cbr.exception.CurrentUserException;
import rs.unicredit.cbr.service.CurrentUserService;

import java.util.List;
import java.util.stream.Collectors;

@Component
public class CurrentUserServiceImpl implements CurrentUserService {

    private Jwt getJwt() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();

        if (auth instanceof JwtAuthenticationToken jwtAuth) {
            return jwtAuth.getToken();
        }

        // nema autentikacije ili nije JWT auth
        throw new CurrentUserException("Current user is not authenticated or token is not a JWT.");
    }

    private Authentication getAuthentication() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (auth == null) {
            throw new CurrentUserException("Current user is not authenticated.");
        }
        return auth;
    }

    @Override
    public String getUsername() {
        Jwt jwt = getJwt();
        String username = jwt.getClaim("preferred_username");

        if (username == null) {
            throw new CurrentUserException("Required claim 'preferred_username' is missing from JWT token.");
        }

        return username;
    }

    @Override
    public String getDepartment() {
        Jwt jwt = getJwt();
        String office = jwt.getClaim("office"); // iz tvog tokena

        if (office == null) {
            throw new CurrentUserException("Required claim 'office' is missing from JWT token.");
        }

        return office;
    }

    @Override
