package rs.unicredit.cbr.service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import rs.unicredit.cbr.dto.GlFeeCalculationResponse;
import rs.unicredit.cbr.model.CbrFeeMatrix;
import rs.unicredit.cbr.model.CbrFeeRuleItem;
import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.repository.CbrFeeMatrixRepository;
import rs.unicredit.cbr.repository.CbrFeeRuleItemRepository;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
public class GlFeeCalculationService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeCalculationService.class);
    private static final String ACTIVE = "Y";
    private static final String STATUS_ENRICHED = "ENRICHED";
    private static final String STATUS_CALC_ERROR = "CALC_ERROR";
    private static final String MODE_FIX = "FIX";
    private static final String MODE_PERCENT = "PERCENT";
    private static final String CCY_RSD = "RSD";
    private static final String CCY_EUR = "EUR";

    private final GlFeeDataRepository glFeeDataRepository;
    private final CbrFeeMatrixRepository cbrFeeMatrixRepository;
    private final CbrFeeRuleItemRepository cbrFeeRuleItemRepository;
    private final GlFeeBookingPreparationService glFeeBookingPreparationService;

    @Transactional
    public GlFeeCalculationResponse calculateFee(String callReplyRef) {
        return calculateFeeForStatus(callReplyRef, STATUS_ENRICHED);
    }

    @Transactional
    public GlFeeCalculationResponse retryCalcError(String callReplyRef) {
        return calculateFeeForStatus(callReplyRef, STATUS_CALC_ERROR);
    }

    private GlFeeCalculationResponse calculateFeeForStatus(String callReplyRef, String expectedStatus) {
        String normalizedCallReplyRef = normalize(callReplyRef);
        if (normalizedCallReplyRef == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "callReplyRef is required");
        }

        GlFeeData feeData = glFeeDataRepository.findByCallReplyRef(normalizedCallReplyRef)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "GL fee data not found for callReplyRef=" + normalizedCallReplyRef));

        if (!expectedStatus.equalsIgnoreCase(normalize(feeData.getBookingStatus()))) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "GL fee data is not in " + expectedStatus + " status for callReplyRef=" + normalizedCallReplyRef
                            + ", currentStatus=" + feeData.getBookingStatus());
        }

        List<CbrFeeMatrix> activeRules = cbrFeeMatrixRepository.findAllByActiveOrderByPriorityAscIdAsc(ACTIVE);
        if (activeRules.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "No active fee matrix rules found");
        }

        Map<String, Set<String>> listCache = new HashMap<>();
        CbrFeeMatrix matchedRule = null;
        for (CbrFeeMatrix rule : activeRules) {
            if (matches(rule, feeData, listCache)) {
                matchedRule = rule;
                break;
            }
        }

        if (matchedRule == null) {
            throw new ResponseStatusException(
                    HttpStatus.NOT_FOUND,
                    "No fee matrix rule matched callReplyRef=" + normalizedCallReplyRef);
        }

        BigDecimal amountBasis = resolveAmountBasis(feeData, matchedRule, normalizedCallReplyRef);
        BigDecimal fee = calculateFeeValue(amountBasis, matchedRule, normalizedCallReplyRef);
        glFeeBookingPreparationService.prepareForBooking(feeData, fee, matchedRule.getRuleNo(), expectedStatus);

        LOG.info(
                "GL fee calculation success feeDataId={} requestId={} callReplyRef={} ruleNo={} ruleName={} amountBasis={} amountBasisCurrency={} fee={} nextStatus={}",
                feeData.getId(),
                feeData.getRequestId(),
                feeData.getCallReplyRef(),
                matchedRule.getRuleNo(),
                matchedRule.getRuleName(),
                amountBasis,
                resolveAmountBasisCurrency(matchedRule),
                fee,
                "PREPARED");

        return GlFeeCalculationResponse.builder()
                .feeDataId(feeData.getId())
                .requestId(feeData.getRequestId())
                .callReplyRef(feeData.getCallReplyRef())
                .bookingStatus(feeData.getBookingStatus())
                .nextBookingStatus("PREPARED")
                .matchedRuleNo(matchedRule.getRuleNo())
                .matchedRuleName(matchedRule.getRuleName())
                .matchedRulePriority(matchedRule.getPriority())
                .feeMode(matchedRule.getFeeMode())
                .amountBasisCurrency(resolveAmountBasisCurrency(matchedRule))
                .amountBasis(amountBasis)
                .feeRate(matchedRule.getFeeRate())
                .feeFixAmount(matchedRule.getFeeFixAmount())
                .feeMin(matchedRule.getFeeMin())
                .feeMax(matchedRule.getFeeMax())
                .calculatedFee(fee)
                .note(matchedRule.getNote())
                .build();
    }

    public int calculateEnrichedRows() {
        List<GlFeeData> candidates = glFeeDataRepository.findAllByBookingStatusOrderByIdAsc(STATUS_ENRICHED);
        int preparedCount = 0;
        for (GlFeeData candidate : candidates) {
            if (candidate == null || candidate.getCallReplyRef() == null) {
                continue;
            }
            try {
                calculateFee(candidate.getCallReplyRef());
                preparedCount++;
            } catch (ResponseStatusException ex) {
                if (isNoRuleMatched(ex)) {
                    LOG.warn(
                            "GL fee calculation left row in ENRICHED because no rule matched feeDataId={} requestId={} callReplyRef={}: {}",
                            candidate.getId(),
                            candidate.getRequestId(),
                            candidate.getCallReplyRef(),
                            ex.getReason());
                    continue;
                }
                markCalcError(candidate);
                LOG.error(
                        "GL fee calculation failed feeDataId={} requestId={} callReplyRef={}: {}",
                        candidate.getId(),
                        candidate.getRequestId(),
                        candidate.getCallReplyRef(),
                        ex.getMessage(),
                        ex);
            } catch (Exception ex) {
                markCalcError(candidate);
                LOG.error(
                        "GL fee calculation failed feeDataId={} requestId={} callReplyRef={}: {}",
                        candidate.getId(),
                        candidate.getRequestId(),
                        candidate.getCallReplyRef(),
                        ex.getMessage(),
                        ex);
            }
        }
        LOG.info("GL fee calculation completed candidates={} prepared={}", candidates.size(), preparedCount);
        return preparedCount;
    }

    private void markCalcError(GlFeeData candidate) {
        glFeeDataRepository.updateBookingStatus(
                candidate.getId(),
                STATUS_ENRICHED,
                STATUS_CALC_ERROR,
                LocalDateTime.now());
    }

    private boolean isNoRuleMatched(ResponseStatusException ex) {
        return ex != null
                && ex.getStatusCode() == HttpStatus.NOT_FOUND
                && ex.getReason() != null
                && ex.getReason().startsWith("No fee matrix rule matched");
    }

    private boolean matches(CbrFeeMatrix rule, GlFeeData feeData, Map<String, Set<String>> listCache) {
        if (rule == null || feeData == null) {
            return false;
        }
        if (!isRuleActiveNow(rule)) {
            return false;
        }
        if (!matchesExact(rule.getMessageType(), feeData.getMessageType())) {
            return false;
        }
        if (!matchesExact(rule.getDirection(), feeData.getDirection())) {
            return false;
        }
        if (!matchesList(rule.getSegmentListCode(), feeData.getSegment(), listCache)) {
            return false;
        }
        if (!matchesList(rule.getDebtorLrcListCode(), feeData.getDebtorLrc(), listCache)) {
            return false;
        }
        if (!matchesList(rule.getCreditorLrcListCode(), feeData.getCreditorLrc(), listCache)) {
            return false;
        }
        if (!matchesList(rule.getFlashListCode(), resolveFlashCandidate(feeData), listCache)) {
            return false;
        }
        if (!matchesOptionalExact(rule.getCrStatisticalCode(), feeData.getCrStatisticalCode())) {
            return false;
        }
        return matchesAmountBand(rule, feeData);
    }

    private boolean isRuleActiveNow(CbrFeeMatrix rule) {
        LocalDate today = LocalDate.now();
        if (rule.getValidFrom() != null && today.isBefore(rule.getValidFrom())) {
            return false;
        }
        if (rule.getValidTo() != null && today.isAfter(rule.getValidTo())) {
            return false;
        }
        return ACTIVE.equalsIgnoreCase(normalize(rule.getActive()));
    }

    private boolean matchesExact(String expected, String actual) {
        return normalize(expected) != null && normalize(expected).equals(normalize(actual));
    }

    private boolean matchesOptionalExact(String expected, String actual) {
        String normalizedExpected = normalize(expected);
        if (normalizedExpected == null) {
            return true;
        }
        return normalizedExpected.equals(normalize(actual));
    }

    private boolean matchesList(String listCode, String actualValue, Map<String, Set<String>> listCache) {
        String normalizedListCode = normalize(listCode);
        if (normalizedListCode == null) {
            return true;
        }
        String normalizedActualValue = normalize(actualValue);
        if (normalizedActualValue == null) {
            return false;
        }
        Set<String> items = listCache.computeIfAbsent(normalizedListCode, this::loadListItems);
        return items.contains(normalizedActualValue);
    }

    private Set<String> loadListItems(String listCode) {
        List<CbrFeeRuleItem> items = cbrFeeRuleItemRepository.findAllByListCodeAndActiveOrderBySortOrderAscIdAsc(
                listCode,
                ACTIVE);
        return items.stream()
                .map(CbrFeeRuleItem::getItemValue)
                .map(this::normalize)
                .filter(value -> value != null)
                .collect(Collectors.toUnmodifiableSet());
    }

    private boolean matchesAmountBand(CbrFeeMatrix rule, GlFeeData feeData) {
        if (rule.getAmountFrom() == null && rule.getAmountTo() == null) {
            return true;
        }
        BigDecimal amountBasis = resolveAmountBasisOrNull(feeData, rule, null);
        if (amountBasis == null) {
            return false;
        }
        if (rule.getAmountFrom() != null && amountBasis.compareTo(rule.getAmountFrom()) < 0) {
            return false;
        }
        if (rule.getAmountTo() != null && amountBasis.compareTo(rule.getAmountTo()) > 0) {
            return false;
        }
        return true;
    }

    private BigDecimal calculateFeeValue(BigDecimal amountBasis, CbrFeeMatrix rule, String callReplyRef) {
        String feeMode = normalize(rule.getFeeMode());
        BigDecimal calculatedFee;
        if (MODE_FIX.equals(feeMode)) {
            if (rule.getFeeFixAmount() == null) {
                throw new ResponseStatusException(
                        HttpStatus.INTERNAL_SERVER_ERROR,
                        "Matched FIX fee rule without FEE_FIX_AMOUNT for callReplyRef=" + callReplyRef
                                + ", ruleNo=" + rule.getRuleNo());
            }
            calculatedFee = rule.getFeeFixAmount();
        } else if (MODE_PERCENT.equals(feeMode)) {
            if (rule.getFeeRate() == null) {
                throw new ResponseStatusException(
                        HttpStatus.INTERNAL_SERVER_ERROR,
                        "Matched PERCENT fee rule without FEE_RATE for callReplyRef=" + callReplyRef
                                + ", ruleNo=" + rule.getRuleNo());
            }
            if (amountBasis == null) {
                throw new ResponseStatusException(
                        HttpStatus.INTERNAL_SERVER_ERROR,
                        "Matched PERCENT fee rule without amount basis for callReplyRef=" + callReplyRef
                                + ", ruleNo=" + rule.getRuleNo());
            }
            calculatedFee = amountBasis.multiply(rule.getFeeRate()).setScale(2, RoundingMode.HALF_UP);
        } else {
            throw new ResponseStatusException(
                    HttpStatus.INTERNAL_SERVER_ERROR,
                    "Matched fee rule has unsupported FEE_MODE for callReplyRef=" + callReplyRef
                            + ", ruleNo=" + rule.getRuleNo()
                            + ", feeMode=" + rule.getFeeMode());
        }

        if (rule.getFeeMin() != null && calculatedFee.compareTo(rule.getFeeMin()) < 0) {
            calculatedFee = rule.getFeeMin();
        }
        if (rule.getFeeMax() != null && calculatedFee.compareTo(rule.getFeeMax()) > 0) {
            calculatedFee = rule.getFeeMax();
        }
        return calculatedFee.setScale(2, RoundingMode.HALF_UP);
    }

    private BigDecimal resolveAmountBasis(GlFeeData feeData, CbrFeeMatrix rule, String callReplyRef) {
        BigDecimal amountBasis = resolveAmountBasisOrNull(feeData, rule, callReplyRef);
        if (amountBasis == null && MODE_PERCENT.equals(normalize(rule.getFeeMode()))) {
            throw new ResponseStatusException(
                    HttpStatus.INTERNAL_SERVER_ERROR,
                    "Amount basis is missing for matched fee rule callReplyRef=" + feeData.getCallReplyRef()
                            + ", ruleNo=" + rule.getRuleNo()
                            + ", amountBasisCurrency=" + resolveAmountBasisCurrency(rule));
        }
        return amountBasis;
    }

    private BigDecimal resolveAmountBasisOrNull(GlFeeData feeData, CbrFeeMatrix rule, String callReplyRef) {
        String amountCcy = normalize(rule.getAmountCcy());
        if (amountCcy == null) {
            throw new ResponseStatusException(
                    HttpStatus.INTERNAL_SERVER_ERROR,
                    "Matched fee rule is missing AMOUNT_CCY for callReplyRef="
                            + (callReplyRef == null ? feeData.getCallReplyRef() : callReplyRef)
                            + ", ruleNo=" + rule.getRuleNo());
        }
        if (CCY_RSD.equals(amountCcy)) {
            return feeData.getAmountRsd();
        }
        if (CCY_EUR.equals(amountCcy)) {
            return feeData.getAmount();
        }
        throw new ResponseStatusException(
                HttpStatus.INTERNAL_SERVER_ERROR,
                "Unsupported AMOUNT_CCY in fee matrix ruleNo=" + rule.getRuleNo() + ": " + rule.getAmountCcy());
    }

    private String resolveAmountBasisCurrency(CbrFeeMatrix rule) {
        return normalize(rule.getAmountCcy());
    }

    private String resolveFlashCandidate(GlFeeData feeData) {
        return feeData.getCreditorAgent();
    }

    private String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed.toUpperCase();
    }
}

