package rs.unicredit.cbr.service;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
public class GlFeeBookingPreparationService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeBookingPreparationService.class);
    private static final String STATUS_ENRICHED = "ENRICHED";
    private static final String STATUS_CALC_ERROR = "CALC_ERROR";
    private static final String STATUS_PREPARED = "PREPARED";
    private static final String NARRATIVE1_PREFIX = "+OV0 Fee ";

    private final GlFeeDataRepository glFeeDataRepository;
    private final GlFeeCreditAccountResolverService glFeeCreditAccountResolverService;

    public void prepareForBooking(GlFeeData feeData, BigDecimal fee, Integer appliedFeeRuleNo) {
        prepareForBooking(feeData, fee, appliedFeeRuleNo, STATUS_ENRICHED);
    }

    public void prepareForBooking(GlFeeData feeData, BigDecimal fee, Integer appliedFeeRuleNo, String currentStatus) {
        if (feeData == null || feeData.getId() == null) {
            throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "Fee data is missing for booking preparation");
        }
        if (fee == null) {
            throw new ResponseStatusException(
                    HttpStatus.INTERNAL_SERVER_ERROR,
                    "Calculated fee is missing for callReplyRef=" + feeData.getCallReplyRef());
        }
        String normalizedCurrentStatus = normalizeCurrentStatus(currentStatus);

        String narrative1 = buildNarrative1(feeData.getCallReplyRef());
        String narrative2 = "";
        Long creditAccount = glFeeCreditAccountResolverService.resolve(feeData.getSdc())
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.INTERNAL_SERVER_ERROR,
                        "Missing credit account mapping for SDC=" + feeData.getSdc()
                                + " callReplyRef=" + feeData.getCallReplyRef()));
        int updated = glFeeDataRepository.updateFeePreparationData(
                feeData.getId(),
                normalizedCurrentStatus,
                STATUS_PREPARED,
                fee,
                creditAccount,
                appliedFeeRuleNo,
                narrative1,
                narrative2,
                LocalDateTime.now());
        if (updated == 0) {
            throw new ResponseStatusException(
                    HttpStatus.INTERNAL_SERVER_ERROR,
                    "Failed to persist prepared booking data for callReplyRef=" + feeData.getCallReplyRef());
        }

        LOG.info(
                "GL fee booking preparation success feeDataId={} requestId={} callReplyRef={} fee={} creditAccount={} appliedFeeRuleNo={} narrative1={} narrative2={} nextStatus={}",
                feeData.getId(),
                feeData.getRequestId(),
                feeData.getCallReplyRef(),
                fee,
                creditAccount,
                appliedFeeRuleNo,
                narrative1,
                narrative2,
                STATUS_PREPARED);
    }

    private String normalizeCurrentStatus(String currentStatus) {
        if (STATUS_ENRICHED.equalsIgnoreCase(currentStatus)) {
            return STATUS_ENRICHED;
        }
        if (STATUS_CALC_ERROR.equalsIgnoreCase(currentStatus)) {
            return STATUS_CALC_ERROR;
        }
        throw new ResponseStatusException(
                HttpStatus.INTERNAL_SERVER_ERROR,
                "Unsupported current status for booking preparation: " + currentStatus);
    }

    private String buildNarrative1(String callReplyRef) {
        if (callReplyRef == null || callReplyRef.isBlank()) {
            throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "callReplyRef is missing for booking preparation");
        }
        return NARRATIVE1_PREFIX + callReplyRef.trim();
    }
}

