import org.mockito.Mock;
import org.mockito.Spy;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.web.server.ResponseStatusException;

import rs.unicredit.cbr.config.GlFeeBookingPreparationProperties;
import rs.unicredit.cbr.dto.GlBookingResponse;
import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.repository.GlFeeBookingLogRepository;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@ExtendWith(MockitoExtension.class)
class GlFeeBookingExecutionServiceTest {

    @Mock
    private GlFeeBookingPreparationProperties glFeeBookingPreparationProperties;

    @Mock
    private GlFeeDataRepository glFeeDataRepository;

    @Mock
    private GlFeeBookingLogRepository glFeeBookingLogRepository;

    @Mock
    private GlBookingService glBookingService;

    @Spy
    @InjectMocks
    private GlFeeBookingExecutionService service;

    @Test
    void executePreparedRowsProcessesPreparedRowsAndSkipsBlankReferences() {
        GlFeeData first = new GlFeeData();
        first.setId(1L);
        first.setRequestId(101L);
        first.setCallReplyRef("REF-1");

        GlFeeData blank = new GlFeeData();
        blank.setId(2L);
        blank.setRequestId(102L);
        blank.setCallReplyRef("   ");

        GlFeeData second = new GlFeeData();
        second.setId(3L);
        second.setRequestId(103L);
        second.setCallReplyRef("REF-2");

        when(glFeeDataRepository.findAllByBookingStatusOrderByIdAsc("PREPARED"))
                .thenReturn(List.of(first, blank, second));

        doReturn(GlBookingResponse.builder().success(true).build()).when(service).executePrepared("REF-1");
        doReturn(GlBookingResponse.builder().success(true).build()).when(service).executePrepared("REF-2");

        int processed = service.executePreparedRows();

        assertThat(processed).isEqualTo(2);
        verify(service).executePrepared("REF-1");
        verify(service).executePrepared("REF-2");
        verify(service, never()).executePrepared("   ");
    }

    @Test
    void executePreparedDoesNotCallGlServiceWhenClaimFails() {
        GlFeeData feeData = new GlFeeData();
        feeData.setId(11L);
        feeData.setRequestId(211L);
        feeData.setCallReplyRef("REF-LOCKED");
        feeData.setBookingStatus("PREPARED");

        when(glFeeDataRepository.findByCallReplyRef("REF-LOCKED"))
                .thenReturn(java.util.Optional.of(feeData));
        when(glFeeDataRepository.updateBookingStatus(eq(11L), eq("PREPARED"), eq("BOOKING_IN_PROGRESS"), any()))
                .thenReturn(0);

        assertThatThrownBy(() -> service.executePrepared("REF-LOCKED"))
                .isInstanceOf(ResponseStatusException.class)
                .hasMessageContaining("already being processed");

        verify(glBookingService, never()).enterGlDealEntryMinimal(any());
    }
}

