package rs.unicredit.cbr.service;

import java.sql.CallableStatement;
import java.sql.Connection;
import java.sql.Types;
import java.util.regex.Pattern;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

import lombok.RequiredArgsConstructor;

@Service
@RequiredArgsConstructor
public class CbrDataArchiveService {

    private static final Pattern PROCEDURE_NAME_PATTERN =
            Pattern.compile("^[A-Za-z][A-Za-z0-9_$#]*(\\.[A-Za-z][A-Za-z0-9_$#]*)?$");

    private final JdbcTemplate jdbcTemplate;

    @Value("${customs.data-archive.procedure-name:CBR.SP_ARCHIVE_CBR_DATA}")
    private String procedureName;

    @Value("${customs.data-archive.days-old:10}")
    private int daysOld;

    public ArchiveResult archiveCompletedData() {
        String validatedProcedureName = validateProcedureName(procedureName);
        String callSql = "{ call " + validatedProcedureName + "(?, ?, ?, ?, ?, ?, ?) }";
        return jdbcTemplate.execute((Connection connection) -> {
            try (CallableStatement cs = connection.prepareCall(callSql)) {
                cs.setInt(1, daysOld);
                cs.registerOutParameter(2, Types.NUMERIC);
                cs.registerOutParameter(3, Types.NUMERIC);
                cs.registerOutParameter(4, Types.NUMERIC);
                cs.registerOutParameter(5, Types.NUMERIC);
                cs.registerOutParameter(6, Types.NUMERIC);
                cs.registerOutParameter(7, Types.NUMERIC);
                cs.execute();

                return new ArchiveResult(
                        getNullableLong(cs, 2),
                        getNullableLong(cs, 3),
                        getNullableLong(cs, 4),
                        getNullableLong(cs, 5),
                        getNullableLong(cs, 6),
                        getNullableLong(cs, 7));
            }
        });
    }

    private String validateProcedureName(String configuredProcedureName) {
        if (configuredProcedureName == null) {
            throw new IllegalStateException("Archive procedure name must not be null");
        }
        String normalized = configuredProcedureName.trim();
        if (!PROCEDURE_NAME_PATTERN.matcher(normalized).matches()) {
            throw new IllegalStateException("Invalid archive procedure name: " + configuredProcedureName);
        }
        return normalized;
    }

    private long getNullableLong(CallableStatement cs, int index) throws java.sql.SQLException {
        long value = cs.getLong(index);
        return cs.wasNull() ? 0L : value;
    }

    public record ArchiveResult(
            long archivedTransactions,
            long archivedTransactionStats,
            long archivedSnapshots,
            long deletedTransactions,
            long deletedTransactionStats,
            long deletedSnapshots) {
    }
}

