package rs.unicredit.cbr.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import lombok.RequiredArgsConstructor;

@Component
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "customs.data-archive", name = "enabled", havingValue = "true")
public class CbrDataArchiveScheduler {

    private static final Logger LOG = LoggerFactory.getLogger(CbrDataArchiveScheduler.class);

    private final CbrDataArchiveService cbrDataArchiveService;

    @Scheduled(
            cron = "${customs.data-archive.cron:0 0 2 * * *}",
            zone = "${customs.data-archive.zone:Europe/Belgrade}")
    public void archiveDaily() {
        CbrDataArchiveService.ArchiveResult result = cbrDataArchiveService.archiveCompletedData();
        LOG.info(
                "CBR data archive completed: archivedTransactions={}, archivedTransactionStats={}, archivedSnapshots={}, "
                        + "deletedTransactions={}, deletedTransactionStats={}, deletedSnapshots={}",
                result.archivedTransactions(),
                result.archivedTransactionStats(),
                result.archivedSnapshots(),
                result.deletedTransactions(),
                result.deletedTransactionStats(),
                result.deletedSnapshots());
    }
}

