package rs.unicredit.cbr.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.sql.CallableStatement;
import java.sql.Connection;
import java.sql.Types;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.jdbc.core.ConnectionCallback;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;

@ExtendWith(MockitoExtension.class)
class CbrDataArchiveServiceTest {

    @Mock
    private JdbcTemplate jdbcTemplate;

    @Mock
    private Connection connection;

    @Mock
    private CallableStatement callableStatement;

    private CbrDataArchiveService service;

    @BeforeEach
    void setUp() throws Exception {
        service = new CbrDataArchiveService(jdbcTemplate);
        ReflectionTestUtils.setField(service, "procedureName", "CBR.SP_ARCHIVE_CBR_DATA");
        ReflectionTestUtils.setField(service, "daysOld", 10);

        when(jdbcTemplate.execute(any(ConnectionCallback.class))).thenAnswer(invocation -> {
            @SuppressWarnings("unchecked")
            ConnectionCallback<CbrDataArchiveService.ArchiveResult> callback =
                    invocation.getArgument(0, ConnectionCallback.class);
            return callback.doInConnection(connection);
        });
        when(connection.prepareCall("{ call CBR.SP_ARCHIVE_CBR_DATA(?, ?, ?, ?, ?, ?, ?) }"))
                .thenReturn(callableStatement);
    }

    @Test
    void archiveCompletedDataMapsAllOutParameters() throws Exception {
        when(callableStatement.getLong(2)).thenReturn(3L);
        when(callableStatement.getLong(3)).thenReturn(5L);
        when(callableStatement.getLong(4)).thenReturn(7L);
        when(callableStatement.getLong(5)).thenReturn(2L);
        when(callableStatement.getLong(6)).thenReturn(4L);
        when(callableStatement.getLong(7)).thenReturn(6L);
        when(callableStatement.wasNull()).thenReturn(false, false, false, false, false, false);

        CbrDataArchiveService.ArchiveResult result = service.archiveCompletedData();

        assertThat(result.archivedTransactions()).isEqualTo(3L);
        assertThat(result.archivedTransactionStats()).isEqualTo(5L);
        assertThat(result.archivedSnapshots()).isEqualTo(7L);
