+    private static final Pattern PROCEDURE_NAME_PATTERN =
+            Pattern.compile("^[A-Za-z][A-Za-z0-9_$#]*(\\.[A-Za-z][A-Za-z0-9_$#]*)?$");
+
+    private final JdbcTemplate jdbcTemplate;
