+    @Value("${customs.fee-booking.archive.procedure-name:CBR.SP_ARCHIVE_GL_FEE_DATA}")
+    private String procedureName;
+
+    @Value("${customs.fee-booking.archive.days-old:10}")
+    private int daysOld;
+
+    public ArchiveResult archiveBookedFeeData() {
+        String validatedProcedureName = validateProcedureName(procedureName);
+        String callSql = "{ call " + validatedProcedureName + "(?, ?, ?, ?, ?) }";
+        return jdbcTemplate.execute((Connection connection) -> {
+            try (CallableStatement cs = connection.prepareCall(callSql)) {
+                cs.setInt(1, daysOld);
+                cs.registerOutParameter(2, Types.NUMERIC);
+                cs.registerOutParameter(3, Types.NUMERIC);
+                cs.registerOutParameter(4, Types.NUMERIC);
+                cs.registerOutParameter(5, Types.NUMERIC);
+                cs.execute();
+
+                return new ArchiveResult(
+                        getNullableLong(cs, 2),
+                        getNullableLong(cs, 3),
+                        getNullableLong(cs, 4),
+                        getNullableLong(cs, 5));
+            }
+        });
+    }
+
+    private String validateProcedureName(String configuredProcedureName) {
+        if (configuredProcedureName == null) {
+            throw new IllegalStateException("GL fee archive procedure name must not be null");
+        }
+        String normalized = configuredProcedureName.trim();
+        if (!PROCEDURE_NAME_PATTERN.matcher(normalized).matches()) {
+            throw new IllegalStateException("Invalid GL fee archive procedure name: " + configuredProcedureName);
+        }
+        return normalized;
+    }
+
+    private long getNullableLong(CallableStatement cs, int index) throws java.sql.SQLException {
+        long value = cs.getLong(index);
+        return cs.wasNull() ? 0L : value;
