    private Optional<List<ValidationApplyResult>> evaluateAllByRequestIdInternal(
            Long requestId,
            boolean updateStatuses,
            boolean transitionOnError,
            boolean afterRestore) {
        if (requestId == null) {
            return Optional.empty();
        }
        try {
            return transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .map(txn -> {
                        List<CbrValidationMatrix> rules = validationMatrixRepository.findAllByOrderByValidationNoAsc();
                        List<ValidationApplyResult> results = new ArrayList<>(rules.size());
                        for (CbrValidationMatrix rule : rules) {
                            if (shouldSkipNonStatCode340Validation(txn, rule)) {
                                LOG.info("Validation {} skipped: stat code 340 allows only 70.3/70.4",
                                        rule.getValidationNo());
                                continue;
                            }
                            if (shouldSkipValidationNoZeroForStatCode1_340(txn, rule)) {
                                LOG.info("Validation {} skipped: stat code1=340", rule.getValidationNo());
                                continue;
                            }
                            if (!matchesMessageTypeAndDirection(txn, rule)) {
                                LOG.info("Validation {} skipped: COND_MESSAGE_TYPE/COND_DIRECTION not matched",
                                        rule.getValidationNo());
                                continue;
                            }
                            ValidationEvaluationResult evaluation = evaluate(txn, rule);
                            LOG.info("Validation {} matched={} failures={}",
                                    evaluation.getValidationNo(), evaluation.isMatched(), evaluation.getFailedConditions());
                            if (evaluation.isMatched()) {
                                ValidationApplyResult applied = applyActionsByValidationNo(
                                        requestId,
                                        evaluation.getValidationNo(),
                                        transitionOnError);
                                results.add(applied);
                            } else {
                                results.add(ValidationApplyResult.builder()
                                        .validationNo(evaluation.getValidationNo())
                                        .matched(false)
                                        .applied(false)
                                        .failedConditions(evaluation.getFailedConditions())
                                        .build());
                            }
                        }
                        long refreshTxnStartedAt = System.currentTimeMillis();
                        CbrTransaction postMatrixTxn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                                .orElse(txn);
                        LOG.info(
                                "Validation flow post-matrix refresh finished requestId={} durationMs={}",
                                requestId,
                                System.currentTimeMillis() - refreshTxnStartedAt);
                        long postMatrixChecksStartedAt = System.currentTimeMillis();
                        appendPostMatrixValidationResults(postMatrixTxn, results);
                        LOG.info(
                                "Validation flow post-matrix checks finished requestId={} durationMs={} resultsCount={} afterRestore={}",
                                requestId,
                                System.currentTimeMillis() - postMatrixChecksStartedAt,
                                results.size(),
                                afterRestore);
                        if (updateStatuses) {
                            long updateStatusesStartedAt = System.currentTimeMillis();
                            if (afterRestore) {
                                updateValidationStatusesAfterRestore(requestId, results);
                            } else {
                                updateValidationStatuses(requestId, results);
                            }
                            LOG.info(
                                    "Validation flow status update finished requestId={} durationMs={} afterRestore={}",
                                    requestId,
                                    System.currentTimeMillis() - updateStatusesStartedAt,
                                    afterRestore);
                        }
                        long saveValidationLogStartedAt = System.currentTimeMillis();
                        saveValidationLog(requestId, results);
                        LOG.info(
                                "Validation flow validation-log save finished requestId={} durationMs={}",
                                requestId,
                                System.currentTimeMillis() - saveValidationLogStartedAt);
                        return results;
                    });
        } catch (Exception ex) {
            if (transitionOnError) {
                stageTransitionService.transitionErrorByRequestId(
                        requestId, "Greska pri obradi svih validation matrix pravila", ex.getMessage());
            }
            throw ex;
        }
    }

    private void appendPostMatrixValidationResults(CbrTransaction txn, List<ValidationApplyResult> results) {
        if (txn == null || results == null) {
            return;
        }
        String reportType = normalize(txn.getReportType());
        if ("60".equals(reportType) || "70".equals(reportType)) {
            if (!isSplitAmountSumValid(txn)) {
                results.add(globalValidationFailure("1", SPLIT_SUM_ERROR_MESSAGE));
            }
            if (!isLoanFieldsValidForSplitStatCode(txn)) {
                results.add(globalValidationFailure("2", LOAN_SPLIT_ERROR_MESSAGE));
            }
            // Validation 3 is temporarily disabled.
            if (!isRule4SplitStatCodeValid(txn)) {
                results.add(globalValidationFailure("4", RULE4_SPLIT_ERROR_MESSAGE));
            }
            if (!isRule5SplitStatCodeValid(txn)) {
                results.add(globalValidationFailure("5", RULE5_SPLIT_ERROR_MESSAGE));
            }
        }
        if ("66".equals(reportType)) {
            if (!isRule6DrCrStatCodeValid(txn)) {
                results.add(globalValidationFailure("6", RULE6_DR_CR_ERROR_MESSAGE));
            }
        }
        if ("77".equals(reportType)) {
            if (!isRule7DrCrStatCodeValid(txn)) {
                results.add(globalValidationFailure("7", RULE7_DR_CR_ERROR_MESSAGE));
            }
        }
        if (!isRule8PaymentInstrumentValid(txn)) {
            results.add(globalValidationFailure("8", RULE8_PAYMENT_INSTRUMENT_ERROR_MESSAGE));
        }
        if (!isRule9SpecialMarkValid(txn)) {
            results.add(globalValidationFailure("9", RULE9_SPECIAL_MARK_ERROR_MESSAGE));
        }
        if (!isRule10CountryCodesValid(txn)) {
            results.add(globalValidationFailure("10", RULE10_COUNTRY_CODES_ERROR_MESSAGE));
        }
        if (!isRule11StatCodesFormatValid(txn)) {
            results.add(globalValidationFailure("11", RULE11_STAT_CODES_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule12CustomerIdFormatValid(txn)) {
            String customerId = txn.getCustomerId();
            String trimmed = customerId == null ? null : customerId.trim();
            LOG.warn("Rule 12 failed for txnId={} requestId={} customerId='{}' trimmed='{}' rawLen={} trimmedLen={}",
                    txn.getId(),
                    txn.getRequest() != null ? txn.getRequest().getId() : null,
                    customerId,
                    trimmed,
                    customerId == null ? null : customerId.length(),
                    trimmed == null ? null : trimmed.length());
            results.add(globalValidationFailure("12", RULE12_CUSTOMER_ID_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule13LoanAndInvoiceYearFormatValid(txn)) {
            results.add(globalValidationFailure("13", RULE13_YEARS_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule14LoanNumberFormatValid(txn)) {
            results.add(globalValidationFailure("14", RULE14_LOAN_NUMBER_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule15InvoiceNumberFormatValid(txn)) {
            results.add(globalValidationFailure("15", RULE15_INVOICE_NUMBER_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule16CountryCode2ForReportType70Valid(txn)) {
            results.add(globalValidationFailure("16", RULE16_COUNTRY_CODE2_REPORT_TYPE70_ERROR_MESSAGE));
        }
    }

    private ValidationApplyResult globalValidationFailure(String validationNo, String message) {
