    private TransferDirection resolveRelatedDirectionForFullStatCopy(String... actionValues) {
        String relatedToken = null;
        for (String actionValue : actionValues) {
            String normalized = normalizeRelatedStatCopyToken(actionValue);
            if (normalized == null) {
                return null;
            }
            if (relatedToken == null) {
                relatedToken = normalized;
            } else if (!relatedToken.equals(normalized)) {
                return null;
            }
        }
        if ("INP8".equals(relatedToken)) {
            return TransferDirection.IN;
        }
        if ("OUTP8".equals(relatedToken)) {
            return TransferDirection.OUT;
        }
        return null;
    }

    private String normalizeRelatedStatCopyToken(String actionValue) {
        if (isBlank(actionValue)) {
            return null;
        }
        String normalized = stripNullDirective(actionValue);
        if (isBlank(normalized) || isExplicitNull(actionValue)) {
            return null;
        }
        String token = normalized.trim().toUpperCase(java.util.Locale.ROOT);
        if ("INP8".equals(token) || "OUTP8".equals(token)) {
            return token;
        }
        return null;
    }

    private boolean replaceRegulatoryDetailsFromRelatedTransaction(CbrTransaction entity, TransferDirection direction) {
        Optional<CbrTransaction> maybeRelated = findRelatedP8Transaction(entity, direction);
        if (maybeRelated.isEmpty()) {
            return false;
        }

        CbrTransaction relatedTxn = maybeRelated.get();
        List<CbrTransactionStat> sourceStats = relatedTxn.getRegulatoryDetails() == null
                ? List.of()
                : relatedTxn.getRegulatoryDetails();

        if (entity.getRegulatoryDetails() == null) {
            entity.setRegulatoryDetails(new ArrayList<>());
        }

        boolean changed = !hasSameRegulatoryDetails(entity.getRegulatoryDetails(), sourceStats);
        entity.getRegulatoryDetails().clear();
        for (CbrTransactionStat sourceStat : sourceStats) {
            CbrTransactionStat clonedStat = new CbrTransactionStat();
            clonedStat.setTransaction(entity);
            clonedStat.setSplitStatCode(sourceStat.getSplitStatCode());
            clonedStat.setSplitAmount(sourceStat.getSplitAmount());
            clonedStat.setSplitAmountCurrency(sourceStat.getSplitAmountCurrency());
            clonedStat.setInvoiceNumber(sourceStat.getInvoiceNumber());
            clonedStat.setInvoiceYear(sourceStat.getInvoiceYear());
            entity.getRegulatoryDetails().add(clonedStat);
        }
        LOG.info(
                "Copied {} regulatory detail rows from related P8 txn id={} to txn id={} direction={}",
                sourceStats.size(),
                relatedTxn.getId(),
                entity.getId(),
                direction);
        return changed;
    }

    private boolean hasSameRegulatoryDetails(List<CbrTransactionStat> left, List<CbrTransactionStat> right) {
        if (left == null || left.isEmpty()) {
            return right == null || right.isEmpty();
        }
        if (right == null || left.size() != right.size()) {
            return false;
        }
        for (int i = 0; i < left.size(); i++) {
            CbrTransactionStat leftStat = left.get(i);
            CbrTransactionStat rightStat = right.get(i);
            if (!java.util.Objects.equals(leftStat.getSplitStatCode(), rightStat.getSplitStatCode())
                    || !java.util.Objects.equals(leftStat.getSplitAmount(), rightStat.getSplitAmount())
                    || !java.util.Objects.equals(leftStat.getSplitAmountCurrency(), rightStat.getSplitAmountCurrency())
                    || !java.util.Objects.equals(leftStat.getInvoiceNumber(), rightStat.getInvoiceNumber())
                    || !java.util.Objects.equals(leftStat.getInvoiceYear(), rightStat.getInvoiceYear())) {
                return false;
            }
        }
        return true;
    }

