import React from "react";
import { Button, Tooltip } from "antd";
import {
  CheckCircleOutlined,
  ExclamationCircleOutlined,
  EyeOutlined,
} from "@ant-design/icons";
import ColumnSearchProps from "../../components/ColumnSearchProps/ColumnSearchProps";
import styles from "../../components/DataTable/DataTable.module.css";
import { resolveStatusPresentation } from "../../utils/statusPresentation";

export const TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY =
  "CBR_COLUMN_VISIBILITY_V5:reference|status|grpSts|coreId|debtorCoreId|orderingPartyName|settlementAmount|settlementDate|currency|userName|receivedDate|p8Reference|stp|contract|entryBy|reworkBy";
export const TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS = [
  "reference",
  "status",
  "grpSts",
  "coreId",
  "debtorCoreId",
  "orderingPartyName",
  "settlementAmount",
  "settlementDate",
  "currency",
  "userName",
  "receivedDate",
  "p8Reference",
];

const formatAmount = (value) => {
  if (value === null || value === undefined || value === "") return "-";
  const number = Number(value);
  if (Number.isNaN(number)) return String(value);
  return number.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

const renderStatusIcon = (tone) =>
  tone === "success" ? (
    <CheckCircleOutlined className={styles.statusIcon} />
  ) : (
    <ExclamationCircleOutlined className={styles.statusIcon} />
  );

const resolveGrpStsPresentation = (value, t) => {
  const normalized = String(value || "").trim().toUpperCase();

  if (normalized === "ACCP") {
    return t("common:grpStsAccepted", { defaultValue: "Prihvacen" });
  }

  if (normalized === "RJCT") {
    return t("common:grpStsRejected", { defaultValue: "Odbijen" });
  }

  return String(value || "").trim() || "-";
};

const getColumnSearchProps = (
  dataIndex,
  label,
  searchText,
  searchedColumn,
  setSearchText,
  setSearchedColumn,
  searchInput,
  t
) =>
  ColumnSearchProps({
    t,
    dataIndex,
    label,
    searchText,
    searchedColumn,
    setSearchText,
    setSearchedColumn,
    searchInput,
  });

const parseDateSortValue = (value) => {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (value instanceof Date) {
    const timestamp = value.getTime();
    return Number.isNaN(timestamp) ? null : timestamp;
  }

  const asText = String(value).trim();
  if (!asText || asText === "-") {
    return null;
  }

  const localDateMatch = asText.match(
    /^(\d{2})[\/.](\d{2})[\/.](\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?$/
  );
  if (localDateMatch) {
    const [, day, month, year, hours = "00", minutes = "00", seconds = "00"] =
      localDateMatch;
    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const isoLikeDateMatch = asText.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2})(?::(\d{2}))?)?/
  );
  if (isoLikeDateMatch) {
    const [, year, month, day, hours = "00", minutes = "00", seconds = "00"] =
      isoLikeDateMatch;
    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const parsed = Date.parse(asText);
  return Number.isNaN(parsed) ? null : parsed;
};

const getReceivedDateSortValue = (record = {}) => {
  const candidates = [
    record?._raw?.createdAt ?? null,
    record?._raw?.created_at ?? null,
    record?._raw?.sourceReceivedAt ?? null,
    record?._raw?.receivedDate ?? null,
    record?._raw?.dateReceived ?? null,
    record?._raw?.processingDate ?? null,
    record?._raw?.createdOn ?? null,
    record?._raw?.createdDate ?? null,
    record?.receivedDate ?? null,
  ];

  for (const candidate of candidates) {
    const parsed = parseDateSortValue(candidate);
    if (parsed !== null) {
      return parsed;
    }
  }

  return 0;
};

const getSettlementDateSortValue = (record = {}) => {
  const candidates = [
    record?._raw?.settlementDate ?? null,
    record?.settlementDate ?? null,
  ];

  for (const candidate of candidates) {
    const parsed = parseDateSortValue(candidate);
    if (parsed !== null) {
      return parsed;
    }
  }

  return 0;
};

const buildSearchableTextColumn = ({
  t,
  searchText,
  searchedColumn,
  setSearchText,
  setSearchedColumn,
  searchInput,
  dataIndex,
  titleKey,
  defaultTitle,
  width,
  ellipsis = false,
}) => ({
  title: t(`columns:${titleKey}`, { defaultValue: defaultTitle }),
  dataIndex,
  key: dataIndex,
  width,
  ellipsis,
  sorter: (a, b) =>
    String(a[dataIndex] || "").localeCompare(String(b[dataIndex] || "")),
  ...getColumnSearchProps(
    dataIndex,
    t(`columns:${titleKey}`, { defaultValue: defaultTitle }),
    searchText,
    searchedColumn,
    setSearchText,
    setSearchedColumn,
    searchInput,
    t
  ),
});

const transactionColumns = (
  t,
  searchText,
  setSearchText,
  searchedColumn,
  setSearchedColumn,
  searchInput,
  onView
) => [
  buildSearchableTextColumn({
    t,
    searchText,
    searchedColumn,
    setSearchText,
    setSearchedColumn,
    searchInput,
    dataIndex: "reference",
    titleKey: "reference",
    defaultTitle: "Referenca",
    width: 130,
  }),
  {
    title: t("columns:status", { defaultValue: "Status" }),
    dataIndex: "status",
    key: "status",
    width: 140,
    sorter: (a, b) =>
      String(a.status || "").localeCompare(String(b.status || "")),
    ...getColumnSearchProps(
      "status",
      t("columns:status", { defaultValue: "Status" }),
      searchText,
      searchedColumn,
      setSearchText,
      setSearchedColumn,
      searchInput,
      t
    ),
    render: (value, record) => {
      const resolved = resolveStatusPresentation(value, record);
      return (
        <span className={`${styles.status} ${styles[`status${resolved.tone}`]}`}>
          {renderStatusIcon(resolved.tone)}
          {resolved.label}
        </span>
      );
    },
  },
  {
    title: t("columns:grpSts", { defaultValue: "GRP status" }),
    dataIndex: "grpSts",
    key: "grpSts",
    width: 70,
    sorter: (a, b) =>
      resolveGrpStsPresentation(a.grpSts, t).localeCompare(
        resolveGrpStsPresentation(b.grpSts, t)
      ),
    ...getColumnSearchProps(
      "grpSts",
      t("columns:grpSts", { defaultValue: "GRP status" }),
      searchText,
      searchedColumn,
      setSearchText,
      setSearchedColumn,
      searchInput,
      t
    ),
    onFilter: (value, record) => {
      const normalizedFilter = String(value ?? "").toLowerCase();
      const rawValue = String(record?.grpSts ?? "").toLowerCase();
      const displayValue = resolveGrpStsPresentation(record?.grpSts, t).toLowerCase();
      return (
        rawValue.includes(normalizedFilter) || displayValue.includes(normalizedFilter)
      );
    },
    render: (value) => resolveGrpStsPresentation(value, t),
  },
  buildSearchableTextColumn({
    t,
