{"command":"@'
$workspace = 'C:\Users\imijajlovic\Documents\workspaces\CBR\cbreporting-frontend'
$sourcePath = Join-Path $workspace 'CBR_tehnicka_dokuemntacija_izvor.md'
$docxPath = Join-Path $workspace 'CBR_tehnicka_dokuemntacija.docx'
$docPath = Join-Path $workspace 'CBR_tehnicka_dokuemntacija.doc'

$lines = Get-Content -Path $sourcePath -Encoding UTF8
$word = $null
$document = $null

try {
    $word = New-Object -ComObject Word.Application
    $word.Visible = $false
    $word.DisplayAlerts = 0
    $document = $word.Documents.Add()
    $selection = $word.Selection

    $firstTitleWritten = $false

    foreach ($rawLine in $lines) {
        $line = [string]$rawLine
        $trimmed = $line.TrimEnd()

        if ([string]::IsNullOrWhiteSpace($trimmed)) {
            $selection.TypeParagraph()
            continue
        }

        if ($trimmed.StartsWith('# ')) {
            if (-not $firstTitleWritten) {
                $selection.Style = 'Title'
                $selection.TypeText($trimmed.Substring(2).Trim())
                $selection.TypeParagraph()
                $firstTitleWritten = $true
            }
            else {
                $selection.Style = 'Heading 1'
                $selection.TypeText($trimmed.Substring(2).Trim())
                $selection.TypeParagraph()
            }
            continue
        }

        if ($trimmed.StartsWith('## ')) {
            $selection.Style = 'Heading 1'
            $selection.TypeText($trimmed.Substring(3).Trim())
            $selection.TypeParagraph()
            continue
        }

        if ($trimmed.StartsWith('### ')) {
            $selection.Style = 'Heading 2'
            $selection.TypeText($trimmed.Substring(4).Trim())
            $selection.TypeParagraph()
            continue
        }

        if ($trimmed.StartsWith('#### ')) {
            $selection.Style = 'Heading 3'
            $selection.TypeText($trimmed.Substring(5).Trim())
            $selection.TypeParagraph()
            continue
        }

        $selection.Style = 'Normal'
        if ($trimmed.StartsWith('- ')) {
            $selection.TypeText([char]0x2022 + ' ' + $trimmed.Substring(2).Trim())
        }
        else {
            $selection.TypeText($trimmed)
        }
        $selection.TypeParagraph()
    }

    if (Test-Path $docxPath) { Remove-Item -Path $docxPath -Force }
    if (Test-Path $docPath) { Remove-Item -Path $docPath -Force }

    $wdFormatDocumentDefault = 16
    $wdFormatDocument = 0
