$relsDir = Join-Path $tempRoot '_rels'
$wordDir = Join-Path $tempRoot 'word'
$zipPath = Join-Path $workspace 'CBR_tehnicka_dokuemntacija.zip'
$docxPath = Join-Path $workspace 'CBR_tehnicka_dokuemntacija.docx'

