if (Test-Path $docxPath) { Remove-Item -Path $docxPath -Force }

New-Item -ItemType Directory -Path $relsDir -Force | Out-Null
New-Item -ItemType Directory -Path $wordDir -Force | Out-Null

$ct = @'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
</Types>
'@
Set-Content -Path (Join-Path $tempRoot '[Content_Types].xml') -Value $ct -Encoding UTF8

$rels = @'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>
'@
Set-Content -Path (Join-Path $relsDir '.rels') -Value $rels -Encoding UTF8

function Escape-XmlText([string]$text) {
  if ($null -eq $text) { return '' }
  return [System.Security.SecurityElement]::Escape($text)
}

$paragraphs = New-Object System.Collections.Generic.List[string]
$lines = Get-Content -Path $sourcePath -Encoding UTF8
$firstTitleWritten = $false

foreach ($line in $lines) {
  $trimmed = ([string]$line).TrimEnd()
  if ([string]::IsNullOrWhiteSpace($trimmed)) {
    $paragraphs.Add('<w:p/>')
    continue
  }

  $text = $trimmed
  $runProps = ''

  if ($trimmed.StartsWith('# ')) {
    $text = $trimmed.Substring(2).Trim()
    if (-not $firstTitleWritten) {
      $runProps = '<w:rPr><w:b/><w:sz w:val="36"/></w:rPr>'
      $firstTitleWritten = $true
    } else {
      $runProps = '<w:rPr><w:b/><w:sz w:val="30"/></w:rPr>'
    }
  } elseif ($trimmed.StartsWith('## ')) {
    $text = $trimmed.Substring(3).Trim()
    $runProps = '<w:rPr><w:b/><w:sz w:val="30"/></w:rPr>'
  } elseif ($trimmed.StartsWith('### ')) {
    $text = $trimmed.Substring(4).Trim()
    $runProps = '<w:rPr><w:b/><w:sz w:val="26"/></w:rPr>'
  } elseif ($trimmed.StartsWith('#### ')) {
    $text = $trimmed.Substring(5).Trim()
    $runProps = '<w:rPr><w:b/><w:sz w:val="24"/></w:rPr>'
  } elseif ($trimmed.StartsWith('- ')) {
    $text = '* ' + $trimmed.Substring(2).Trim()
  }

  $escaped = Escape-XmlText $text
  $paragraph = '<w:p><w:r>' + $runProps + '<w:t xml:space="preserve">' + $escaped + '</w:t></w:r></w:p>'
  $paragraphs.Add($paragraph)
}

$body = ($paragraphs -join "`r`n    ")
$documentXml = @"
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:wpc="http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:wp14="http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:w10="urn:schemas-microsoft-com:office:word" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:wpg="http://schemas.microsoft.com/office/word/2010/wordprocessingGroup" xmlns:wpi="http://schemas.microsoft.com/office/word/2010/wordprocessingInk" xmlns:wne="http://schemas.microsoft.com/office/2006/wordml" xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape" mc:Ignorable="w14 wp14">
  <w:body>
    $body
    <w:sectPr>
      <w:pgSz w:w="11906" w:h="16838"/>
      <w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="708" w:footer="708" w:gutter="0"/>
    </w:sectPr>
  </w:body>
</w:document>
"@
Set-Content -Path (Join-Path $wordDir 'document.xml') -Value $documentXml -Encoding UTF8
Compress-Archive -Path (Join-Path $tempRoot '*') -DestinationPath $zipPath -Force
Rename-Item -Path $zipPath -NewName 'CBR_tehnicka_dokuemntacija.docx'
Remove-Item -Path $tempRoot -Recurse -Force
Get-ChildItem $docxPath | Select-Object Name,Length,LastWriteTime","login":false,"workdir":"C:\Users\imijajlovic\Documents\workspaces\CBR\cbreporting-frontend","timeout_ms":120000}

