function Escape-Xml([string]$text) {
  if ($null -eq $text) { return '' }
  return [System.Security.SecurityElement]::Escape($text)
}
function Para([string]$text, [int]$size = 22, [bool]$bold = $false) {
  $escaped = Escape-Xml $text
  $b = if ($bold) { '<w:b/>' } else { '' }
  return ('<w:p><w:r><w:rPr>{0}<w:sz w:val="{1}"/></w:rPr><w:t xml:space="preserve">{2}</w:t></w:r></w:p>' -f $b, $size, $escaped)
}
