} from "../../components/routes";
import {
  getAll as getIncomingAll,
  getErrors as getIncomingErrors,
  searchArchive as searchIncomingArchive,
} from "../../services/incomingService/service";
import {
  getAll as getOutgoingAll,
  getErrors as getOutgoingErrors,
  searchArchive as searchOutgoingArchive,
} from "../../services/outgoingService/service";
import {
  extractTransactionItems,
  mapTransactionListItems,
} from "../../utils/transactionListMapper";
import {
  createTransactionColumns,
