  TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITH_SUSPICIOUS,
  TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITHOUT_SUSPICIOUS,
} from "../shared/transactionColumns";

const firstRejectedReason = (results = []) => {
  const rejected = results.find((entry) => entry?.status === "rejected");
  return rejected?.reason || new Error("Neuspesno ucitavanje podataka.");
};

const mergeRequests = async (requests = [], options = {}) => {
  const { onPartial } = options;
  const successful = [];
  const results = await Promise.allSettled(
    requests.map(async (request) => {
      const response = await request();
      const extractedItems = extractTransactionItems(response);
      if (extractedItems.length) {
        successful.push(...extractedItems);
        onPartial?.([...successful]);
      }
      return response;
    })
  );

  if (successful.length === 0) {
    throw firstRejectedReason(results);
  }

  return successful;
};

const getCombinedAll = (options = {}) =>
  mergeRequests([() => getIncomingAll(), () => getOutgoingAll()], options);

const getCombinedErrors = (options = {}) =>
  mergeRequests([() => getIncomingErrors(), () => getOutgoingErrors()], options);

const ALL_ORDERS_ROUTE_SETTINGS = [
  {
    path: ALL_ORDERS_OUTGOING,
    titleKey: "sidebar:outgoingOrders",
    titleDefault: "PlaÄ‡anja",
    loadData: getOutgoingAll,
    fallbackLoadData: getCombinedAll,
    archiveSearchRequests: [searchOutgoingArchive],
  },
  {
    path: ALL_ORDERS_INCOMING,
    titleKey: "sidebar:incomingOrders",
    titleDefault: "Prilivi",
    loadData: getIncomingAll,
    fallbackLoadData: getCombinedAll,
    archiveSearchRequests: [searchIncomingArchive],
  },
  {
    path: ALL_ORDERS_ERRORS,
    titleKey: "sidebar:errors",
    titleDefault: "GreÅ¡ke",
    loadData: getCombinedErrors,
    fallbackLoadData: getCombinedAll,
    supportsProgressiveResults: true,
    archiveSearchRequests: [searchIncomingArchive, searchOutgoingArchive],
  },
  {
    path: ALL_ORDERS,
    titleKey: "sidebar:allOrders",
    titleDefault: "Sve poruke",
    loadData: getCombinedAll,
    supportsProgressiveResults: true,
    archiveSearchRequests: [searchIncomingArchive, searchOutgoingArchive],
  },
];

const normalizePath = (path) => {
  if (!path) return "";
  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
  return path;
};

const resolveRouteSettings = (pathname) => {
  const normalizedPath = normalizePath(pathname);
  const matchedRoute = ALL_ORDERS_ROUTE_SETTINGS.find(
    (route) => normalizePath(route.path) === normalizedPath
  );
  return (
    matchedRoute ||
    ALL_ORDERS_ROUTE_SETTINGS.find((route) => route.path === ALL_ORDERS) ||
    ALL_ORDERS_ROUTE_SETTINGS[0]
  );
};

const toTransactionItems = (responseOrItems) => {
  if (Array.isArray(responseOrItems)) return responseOrItems;
  return extractTransactionItems(responseOrItems);
};

const AllOrdersBase = ({ t }) => {
  const location = useLocation();
  const {
    titleKey,
    titleDefault,
    loadData,
    fallbackLoadData,
    supportsProgressiveResults,
    archiveSearchRequests = [],
  } = useMemo(
    () => resolveRouteSettings(location.pathname),
    [location.pathname]
  );
  const showSuspiciousFlagColumn = useMemo(
    () => normalizePath(location.pathname) !== normalizePath(ALL_ORDERS_OUTGOING),
    [location.pathname]
  );
  const columns = useMemo(
    () =>
      createTransactionColumns({
        showSuspiciousFlagColumn,
      }),
    [showSuspiciousFlagColumn]
  );
  const defaultVisibleColumnKeys = showSuspiciousFlagColumn
    ? TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS_WITH_SUSPICIOUS
    : TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS_WITHOUT_SUSPICIOUS;
  const columnVisibilityStorageKey = showSuspiciousFlagColumn
    ? TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITH_SUSPICIOUS
    : TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITHOUT_SUSPICIOUS;
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState(null);

  const refreshCurrentRouteItems = useCallback(
    async (options = {}) => {
      const { showLoading = false } = options;
      const progressiveOptions = supportsProgressiveResults
        ? {
            onPartial: (partialItems) => {
              const mappedItems = mapTransactionListItems(
                toTransactionItems(partialItems)
              );
              setItems(mappedItems);
              if (showLoading) {
                setLoading(false);
              }
            },
          }
        : undefined;

      if (showLoading) {
        setLoading(true);
      }

      try {
        try {
          const response = await loadData(progressiveOptions);
          const mappedItems = mapTransactionListItems(
            toTransactionItems(response)
          );
          setItems(mappedItems);
          return;
        } catch (primaryError) {
          if (!fallbackLoadData) {
            return;
          }
        }

        try {
          const response = await fallbackLoadData(progressiveOptions);
          const mappedItems = mapTransactionListItems(
            toTransactionItems(response)
          );
          setItems(mappedItems);
        } catch (fallbackError) {
          // Keep current optimistic row state if refresh fails.
        }
      } finally {
        if (showLoading) {
          setLoading(false);
        }
      }
    },
    [fallbackLoadData, loadData, supportsProgressiveResults]
  );

  const handleReload = useCallback(() => {
    void refreshCurrentRouteItems({ showLoading: true });
  }, [refreshCurrentRouteItems]);

  const handleArchiveSearch = useCallback(
    async (criteria = {}) => {
      const requests = Array.isArray(archiveSearchRequests)
        ? archiveSearchRequests.filter((request) => typeof request === "function")
        : [];

      if (!requests.length) {
        return false;
      }

      setLoading(true);
      try {
        const results = await Promise.allSettled(
          requests.map((request) => request(criteria))
        );
        const fulfilledResponses = results
          .filter((result) => result.status === "fulfilled")
          .map((result) => result.value);

        if (fulfilledResponses.length === 0) {
          throw firstRejectedReason(results);
        }

        const mergedItems = fulfilledResponses.flatMap((response) =>
          extractTransactionItems(response)
        );
        const mappedItems = mapTransactionListItems(mergedItems);
        setItems(mappedItems);
        return true;
      } catch (error) {
        Notification(
          t("common:errorTitle", { defaultValue: "Greska" }),
          error?.response?.data?.message ||
            t("common:archiveSearchFailed", {
              defaultValue: "Neuspesna pretraga arhive.",
            }),
          "error",
          "topRight"
        );
        return false;
      } finally {
        setLoading(false);
      }
    },
    [archiveSearchRequests, t]
  );

  const handleView = (record) => {
    if (record?.canOpenDrawer === false) {
      return;
    }
    setSelectedOrder(record || null);
    setIsDrawerOpen(true);
  };

  const handleCloseDrawer = () => {
    setIsDrawerOpen(false);
  };

  const handleOrderUpdated = (updatedOrder) => {
    if (!updatedOrder || updatedOrder.id === null || updatedOrder.id === undefined) {
      return;
    }

    setSelectedOrder(updatedOrder);
    setItems((currentItems) =>
      currentItems.map((item) => {
        if (String(item?.id) !== String(updatedOrder.id)) {
          return item;
        }
        return {
          ...item,
          ...updatedOrder,
          statusCode: updatedOrder.statusCode || item?.statusCode,
          status: updatedOrder.status || item?.status,
          _raw: {
            ...(item?._raw || {}),
            ...(updatedOrder?._raw || {}),
          },
        };
      })
    );

    void refreshCurrentRouteItems();
  };

  useEffect(() => {
    if (top !== self) {
      top.location = self.location;
    }

    let cancelled = false;

    const fetchAllOrders = async () => {
      setLoading(true);
      try {
        const response = await loadData(
          supportsProgressiveResults
            ? {
                onPartial: (partialItems) => {
                  const mappedItems = mapTransactionListItems(
                    toTransactionItems(partialItems)
                  );
                  if (!cancelled) {
                    setItems(mappedItems);
                    setLoading(false);
                  }
                },
              }
            : undefined
        );
        const mappedItems = mapTransactionListItems(
          toTransactionItems(response)
        );
        if (!cancelled) {
          setItems(mappedItems);
        }
      } catch (primaryError) {
        if (!fallbackLoadData) {
          if (!cancelled) {
            Notification(
              t("notification:incoming:error", { defaultValue: "Greska" }),
              t("notification:incoming:message", {
                defaultValue: "Neuspesno ucitavanje podataka.",
              }),
              "error",
              "topRight"
            );
          }
          return;
        }

        try {
          const response = await fallbackLoadData(
            supportsProgressiveResults
              ? {
                  onPartial: (partialItems) => {
                    const mappedItems = mapTransactionListItems(
                      toTransactionItems(partialItems)
                    );
                    if (!cancelled) {
                      setItems(mappedItems);
                      setLoading(false);
                    }
                  },
                }
              : undefined
          );
          const mappedItems = mapTransactionListItems(
            toTransactionItems(response)
          );
          if (!cancelled) {
            setItems(mappedItems);
          }
        } catch (fallbackError) {
          if (!cancelled) {
            Notification(
              t("notification:incoming:error", { defaultValue: "Greska" }),
              t("notification:incoming:message", {
                defaultValue: "Neuspesno ucitavanje podataka.",
              }),
              "error",
              "topRight"
            );
          }
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    fetchAllOrders();

    return () => {
      cancelled = true;
    };
  }, [fallbackLoadData, loadData, supportsProgressiveResults, t]);

  return (
    <>
      <Header title={t(titleKey, { defaultValue: titleDefault })} />
      <DataTable
        items={items}
        columns={columns}
        loading={loading}
        onReload={handleReload}
        onView={handleView}
        defaultVisibleColumnKeys={defaultVisibleColumnKeys}
        columnVisibilityStorageKey={columnVisibilityStorageKey}
      />
      <Drawer
        open={isDrawerOpen}
        onClose={handleCloseDrawer}
        selectedOrder={selectedOrder}
        onOrderUpdated={handleOrderUpdated}
      />
    </>
  );
};

export default withTranslation(["privatePage"])(AllOrdersBase);

